-- Ta'mir: БОШЛАНҒИЧ СХЕМА (baseline). Test базадан (mlhhmohaxpetptmrtqrz) 2026-10-21 да олинган экспортдан ясалган.
-- Нима учун: prod'ни кейин НОЛДАН шу файл + кейинги миграциялар билан қуриш учун. Маълумот йўқ, фақат тузилма.
-- Қаерда ишлатилади: ФАҚАТ ЯНГИ, БЎШ Supabase лойиҳада. Мавжуд test базада ИШЛАТМАНГ (ҳаммаси бор, хато беради).
-- Тартиб: шу файл -> 20261021_01_tighten_table_grants.sql -> кейингилари.
-- Эслатма: устунлар тартиби алфавит бўйича (экспортда асл тартиб йўқ эди), бу кодга таъсир қилмайди.
-- Эслатма: id устунлари "generated by default as identity" деб олинган (экспортда шу белги кўринмайди).
-- Эслатма: pg_cron жадвали (cron.job) ва app_settings қийматлари бу ерда йўқ, улар алоҳида қўйилади.

begin;
set local check_function_bodies = off;

-- 0. Кенгайтмалар (Supabase'да pgcrypto, uuid-ossp, vault аллақачон бор)
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
create extension if not exists "uuid-ossp" with schema extensions;
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_net') then
    create extension if not exists pg_net;
  end if;
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
  end if;
end $$;

-- 1. Жадваллар
create table public.admin_alerts (
  created_at timestamp with time zone not null default now(),
  id bigint generated by default as identity not null,
  key text not null,
  lvl text not null,
  order_no bigint,
  resolved_at timestamp with time zone,
  text text not null
);

create table public.admin_sessions (
  admin_id bigint not null,
  created_at timestamp with time zone not null default now(),
  ended_at timestamp with time zone,
  expires_at timestamp with time zone not null,
  id bigint generated by default as identity not null,
  last_seen timestamp with time zone not null default now(),
  profile_id bigint not null,
  token_hash text not null
);

create table public.admin_users (
  created_at timestamp with time zone not null default now(),
  failed integer not null default 0,
  id bigint generated by default as identity not null,
  locked_until timestamp with time zone,
  name text not null default ''::text,
  pin_hash text,
  profile_id bigint not null,
  roles text[] not null default '{operator}'::text[],
  status text not null default 'active'::text
);

create table public.app_settings (
  key text not null,
  value text not null
);

create table public.audit_log (
  action text not null,
  admin_id bigint,
  admin_name text,
  at timestamp with time zone not null default now(),
  id bigint generated by default as identity not null,
  new_value jsonb,
  obj_id text,
  object text,
  old_value jsonb,
  reason text
);

create table public.collector_login (
  created_at timestamp with time zone not null default now(),
  seller_id bigint,
  token text not null,
  used_at timestamp with time zone
);

create table public.collector_sessions (
  created_at timestamp with time zone not null default now(),
  expires_at timestamp with time zone not null default (now() + '365 days'::interval),
  last_seen timestamp with time zone not null default now(),
  seller_id bigint not null,
  token_hash text not null
);

create table public.delivery_tariffs (
  active boolean not null default true,
  cap_kg integer not null,
  emoji text default '🚚'::text,
  far_price bigint not null,
  hint text,
  id text not null,
  mid_price bigint not null,
  name text not null,
  near_price bigint not null,
  sort integer not null default 100
);

create table public.driver_login (
  created_at timestamp with time zone not null default now(),
  seller_id bigint,
  token text not null,
  used_at timestamp with time zone
);

create table public.driver_sessions (
  created_at timestamp with time zone not null default now(),
  expires_at timestamp with time zone not null default (now() + '365 days'::interval),
  last_seen timestamp with time zone not null default now(),
  seller_id bigint not null,
  token_hash text not null
);

create table public.events (
  anon text not null,
  at timestamp with time zone not null default now(),
  id bigint generated by default as identity not null,
  kind text not null,
  props jsonb not null default '{}'::jsonb
);

create table public.fee_settings (
  key text not null,
  note text,
  value numeric not null
);

create table public.fleets (
  active boolean not null default true,
  created_at timestamp with time zone not null default now(),
  id bigint generated by default as identity not null,
  market_id integer,
  name text not null,
  phone text
);

create table public.ledger (
  amount bigint not null,
  created_at timestamp with time zone not null default now(),
  id bigint generated by default as identity not null,
  kind text not null,
  note text,
  order_no bigint not null,
  reverses bigint
);

create table public.login_tokens (
  consent boolean not null default false,
  created_at timestamp with time zone not null default now(),
  profile_id bigint,
  tg_chat_id bigint,
  token text not null,
  uid uuid not null,
  used_at timestamp with time zone
);

create table public.markets (
  active boolean not null default true,
  address text,
  district text,
  id integer generated by default as identity not null,
  lat double precision,
  lng double precision,
  name text not null,
  name_uz text,
  pickers_max integer not null default 2,
  size text not null default 'medium'::text,
  sort integer not null default 100
);

create table public.notes (
  admin_id bigint,
  admin_name text,
  at timestamp with time zone not null default now(),
  body text not null,
  id bigint generated by default as identity not null,
  kind text not null,
  ref text not null
);

create table public.offers (
  in_stock boolean not null default true,
  price bigint not null,
  product_id integer not null,
  seller_id bigint not null,
  updated_at timestamp with time zone not null default now()
);

create table public.order_lines (
  client_price bigint not null default 0,
  line_no integer not null,
  loaded boolean not null default false,
  msg_id bigint,
  name text not null,
  offered_at timestamp with time zone,
  order_no bigint not null,
  price bigint,
  product_id integer,
  qty numeric not null,
  says_yes boolean not null default true,
  seller_id bigint,
  status text not null default 'pending'::text,
  tried bigint[] not null default '{}'::bigint[],
  unit text not null default ''::text
);

create table public.order_msgs (
  confirmed_at timestamp with time zone,
  created_at timestamp with time zone not null default now(),
  expired_at timestamp with time zone,
  id bigint generated by default as identity not null,
  order_no bigint not null,
  ready_at timestamp with time zone,
  seller_id bigint not null,
  tg_message_id bigint
);

create table public.orders (
  address text,
  alerted_at timestamp with time zone,
  body text,
  collector_fee bigint,
  created_at timestamp with time zone not null default now(),
  customer_name text not null,
  delivery_lat double precision,
  delivery_lng double precision,
  delivery_sum bigint,
  driver_at timestamp with time zone,
  driver_fee bigint,
  driver_id bigint,
  driver_info jsonb,
  driver_lat double precision,
  driver_lng double precision,
  eta_min integer,
  fleet_alerted boolean not null default false,
  fleet_dispatched_at timestamp with time zone,
  gateway_fee bigint,
  gateway_pct numeric,
  goods boolean not null default true,
  goods_sum bigint,
  items jsonb not null,
  loaded_at timestamp with time zone,
  market_id integer,
  mode text not null,
  no bigint generated by default as identity not null,
  note text,
  notified_at timestamp with time zone,
  paid_at timestamp with time zone,
  pay_amount bigint,
  pay_due timestamp with time zone,
  pay_provider text,
  pay_status text not null default 'none'::text,
  payout_release boolean not null default false,
  phone text not null,
  pick_total integer not null default 0,
  picked integer not null default 0,
  picker_id bigint,
  picker_info jsonb,
  pickup_at timestamp with time zone,
  pickup_lat double precision,
  pickup_lng double precision,
  pickup_note text,
  platform_income bigint,
  profile_id bigint,
  provider text,
  received_at timestamp with time zone,
  received_note text,
  received_ok boolean,
  reserve_sum bigint not null default 0,
  seller_commission bigint not null default 0,
  service_fee bigint,
  slot text,
  stage integer not null default 0,
  times jsonb not null default '[]'::jsonb,
  total bigint not null,
  trips integer,
  user_id uuid not null default auth.uid(),
  weight_kg numeric,
  work boolean not null default false,
  zone text
);

create table public.payment_providers (
  code text not null,
  enabled boolean not null default true,
  name text not null,
  pct numeric not null default 0,
  sort integer not null default 100
);

create table public.payments (
  amount bigint not null,
  cancelled_at timestamp with time zone,
  created_at timestamp with time zone not null default now(),
  ext jsonb not null default '{}'::jsonb,
  id bigint generated by default as identity not null,
  order_no bigint not null,
  paid_at timestamp with time zone,
  provider text not null,
  provider_trans_id text not null,
  status text not null default 'created'::text
);

create table public.price_history (
  admin_id bigint,
  at timestamp with time zone not null default now(),
  id bigint generated by default as identity not null,
  new_price bigint not null,
  old_price bigint,
  product_id integer not null,
  seller_id bigint not null,
  source text not null default 'admin'::text
);

create table public.products (
  active boolean not null default true,
  base_price bigint not null default 0,
  cat text not null,
  emoji text not null default ''::text,
  id integer generated by default as identity not null,
  name text not null,
  spec text not null default ''::text,
  unit text not null,
  weight_kg numeric
);

create table public.profile_devices (
  created_at timestamp with time zone not null default now(),
  profile_id bigint not null,
  uid uuid not null
);

create table public.profiles (
  addresses jsonb not null default '[]'::jsonb,
  block_reason text,
  consent_at timestamp with time zone,
  created_at timestamp with time zone not null default now(),
  id bigint generated by default as identity not null,
  lang text not null default 'uz'::text,
  last_seen_at timestamp with time zone not null default now(),
  name text,
  phone text,
  tags text[] not null default '{}'::text[],
  tg_id bigint
);

create table public.purchases (
  collector_id bigint not null,
  commission bigint not null default 0,
  commission_pct numeric not null default 0,
  created_at timestamp with time zone not null default now(),
  id bigint generated by default as identity not null,
  items jsonb not null,
  order_no bigint not null,
  paid_at timestamp with time zone,
  payable bigint,
  shop_id bigint not null,
  status text not null default 'pending'::text,
  total bigint not null
);

create table public.refunds (
  amount bigint not null,
  created_at timestamp with time zone not null default now(),
  created_by bigint,
  done_at timestamp with time zone,
  done_by bigint,
  id bigint generated by default as identity not null,
  kind text not null,
  order_no bigint not null,
  reason text,
  status text not null default 'pending'::text
);

create table public.sellers (
  active boolean not null default true,
  block_reason text,
  car text,
  card text,
  categories text[] not null default '{}'::text[],
  code text not null default substr(md5(((random())::text || (clock_timestamp())::text)), 1, 12),
  commission_pct numeric,
  created_at timestamp with time zone not null default now(),
  fleet_id bigint,
  id bigint generated by default as identity not null,
  license_no text,
  license_photo text,
  market_id integer,
  name text not null default ''::text,
  phone text,
  reg_step text,
  role text not null default 'seller'::text,
  row_no text,
  shop text not null default ''::text,
  status text not null default 'active'::text,
  tg_chat_id bigint
);

create table public.staff_payouts (
  admin_id bigint,
  amount bigint not null,
  at timestamp with time zone not null default now(),
  id bigint generated by default as identity not null,
  note text,
  seller_id bigint not null
);

create table public.ticket_msgs (
  admin_name text,
  at timestamp with time zone not null default now(),
  body text not null,
  from_role text not null,
  id bigint generated by default as identity not null,
  ticket_id bigint not null
);

create table public.tickets (
  closed_at timestamp with time zone,
  closed_by bigint,
  created_at timestamp with time zone not null default now(),
  decision text,
  decision_amount bigint,
  id bigint generated by default as identity not null,
  order_no bigint,
  profile_id bigint not null,
  status text not null default 'open'::text
);

