alter table public.admin_sessions add constraint "admin_sessions_token_hash_key" UNIQUE (token_hash);
alter table public.admin_users add constraint "admin_users_profile_id_key" UNIQUE (profile_id);
alter table public.payments add constraint "payments_provider_provider_trans_id_key" UNIQUE (provider, provider_trans_id);
alter table public.profiles add constraint "profiles_tg_id_key" UNIQUE (tg_id);
alter table public.sellers add constraint "sellers_code_key" UNIQUE (code);
alter table public.admin_alerts add constraint "admin_alerts_lvl_check" CHECK ((lvl = ANY (ARRAY['red'::text, 'yellow'::text, 'info'::text])));
alter table public.admin_users add constraint "admin_roles_ok" CHECK (((roles <@ ARRAY['owner'::text, 'operator'::text, 'accountant'::text, 'support'::text]) AND (cardinality(roles) > 0)));
alter table public.admin_users add constraint "admin_users_status_check" CHECK ((status = ANY (ARRAY['active'::text, 'blocked'::text])));
alter table public.ledger add constraint "ledger_kind_check" CHECK ((kind = ANY (ARRAY['customer_payment'::text, 'shop_goods'::text, 'driver_pay'::text, 'collector_pay'::text, 'gateway_fee'::text, 'platform_income'::text, 'refund'::text, 'reserve_hold'::text])));
alter table public.markets add constraint "markets_size_check" CHECK ((size = ANY (ARRAY['small'::text, 'medium'::text, 'large'::text])));
alter table public.notes add constraint "notes_kind_check" CHECK ((kind = ANY (ARRAY['order'::text, 'customer'::text, 'seller'::text])));
alter table public.offers add constraint "offers_price_check" CHECK ((price > 0));
alter table public.order_lines add constraint "order_lines_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'offered'::text, 'confirmed'::text, 'ready'::text, 'missing'::text])));
alter table public.orders add constraint "orders_mode_check" CHECK ((mode = ANY (ARRAY['delivery'::text, 'pickup'::text, 'car'::text])));
alter table public.orders add constraint "orders_pay_status_check" CHECK ((pay_status = ANY (ARRAY['none'::text, 'unpaid'::text, 'paid'::text, 'expired'::text, 'refunded'::text])));
alter table public.orders add constraint "orders_stage_check" CHECK ((stage >= 0));
alter table public.orders add constraint "orders_total_check" CHECK ((total >= 0));
alter table public.payments add constraint "payments_amount_check" CHECK ((amount > 0));
alter table public.payments add constraint "payments_provider_check" CHECK ((provider = ANY (ARRAY['click'::text, 'payme'::text, 'test'::text])));
alter table public.payments add constraint "payments_status_check" CHECK ((status = ANY (ARRAY['created'::text, 'paid'::text, 'cancelled'::text])));
alter table public.purchases add constraint "purchases_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'paid'::text, 'rejected'::text])));
alter table public.refunds add constraint "refunds_amount_check" CHECK ((amount > 0));
alter table public.refunds add constraint "refunds_kind_check" CHECK ((kind = ANY (ARRAY['reserve'::text, 'item'::text, 'cancel'::text, 'other'::text])));
alter table public.refunds add constraint "refunds_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'done'::text])));
alter table public.sellers add constraint "sellers_commission_pct_check" CHECK (((commission_pct IS NULL) OR ((commission_pct >= (0)::numeric) AND (commission_pct <= (30)::numeric))));
alter table public.sellers add constraint "sellers_role_check" CHECK ((role = ANY (ARRAY['seller'::text, 'collector'::text, 'driver'::text, 'admin'::text])));
alter table public.sellers add constraint "sellers_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'blocked'::text])));
alter table public.staff_payouts add constraint "staff_payouts_amount_check" CHECK ((amount > 0));
alter table public.ticket_msgs add constraint "ticket_msgs_from_role_check" CHECK ((from_role = ANY (ARRAY['customer'::text, 'admin'::text])));
alter table public.tickets add constraint "tickets_decision_check" CHECK ((decision = ANY (ARRAY['accept'::text, 'partial'::text, 'reject'::text])));
alter table public.tickets add constraint "tickets_status_check" CHECK ((status = ANY (ARRAY['open'::text, 'answered'::text, 'closed'::text])));
alter table public.admin_sessions add constraint "admin_sessions_admin_id_fkey" FOREIGN KEY (admin_id) REFERENCES public.admin_users(id);
