-- 3. Индекслар (калитлар ўзи яратганлари бундан ташқари)
CREATE UNIQUE INDEX admin_alerts_open_key ON public.admin_alerts USING btree (key) WHERE (resolved_at IS NULL);
CREATE INDEX audit_at_idx ON public.audit_log USING btree (at DESC);
CREATE INDEX events_at_idx ON public.events USING btree (at);
CREATE INDEX events_kind_idx ON public.events USING btree (kind, at);
CREATE INDEX ledger_order_idx ON public.ledger USING btree (order_no);
CREATE INDEX login_tokens_chat_idx ON public.login_tokens USING btree (tg_chat_id, created_at DESC);
CREATE INDEX notes_ref ON public.notes USING btree (kind, ref, at DESC);
CREATE INDEX offers_product_idx ON public.offers USING btree (product_id, price) WHERE in_stock;
CREATE INDEX order_lines_offered_idx ON public.order_lines USING btree (offered_at) WHERE (status = 'offered'::text);
CREATE INDEX order_msgs_order_idx ON public.order_msgs USING btree (order_no);
CREATE INDEX orders_pay_due_idx ON public.orders USING btree (pay_due) WHERE (pay_status = 'unpaid'::text);
CREATE INDEX orders_profile_idx ON public.orders USING btree (profile_id, no DESC);
CREATE INDEX orders_user_idx ON public.orders USING btree (user_id, no DESC);
CREATE UNIQUE INDEX payments_one_paid ON public.payments USING btree (order_no) WHERE (status = 'paid'::text);
CREATE INDEX payments_order_idx ON public.payments USING btree (order_no);
CREATE INDEX price_history_pr ON public.price_history USING btree (product_id, at DESC);
CREATE INDEX profile_devices_profile_idx ON public.profile_devices USING btree (profile_id);
CREATE INDEX purchases_order_idx ON public.purchases USING btree (order_no);
CREATE INDEX sellers_chat_idx ON public.sellers USING btree (tg_chat_id);
CREATE INDEX sellers_market_idx ON public.sellers USING btree (market_id, role);
CREATE INDEX staff_payouts_s ON public.staff_payouts USING btree (seller_id, at DESC);
CREATE INDEX ticket_msgs_t ON public.ticket_msgs USING btree (ticket_id, id);
CREATE INDEX tickets_profile ON public.tickets USING btree (profile_id, created_at DESC);
CREATE INDEX tickets_status ON public.tickets USING btree (status, created_at DESC);

-- 4. Функциялар
CREATE OR REPLACE FUNCTION public.admin_admin_add(p_code text, p_phone text, p_roles text[], p_name text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pr public.profiles; id bigint; d text := regexp_replace(coalesce(p_phone, ''), '\D', '', 'g');
begin
  perform public.admin_check(p_code); perform public.admin_need('admins');
  if length(d) < 9 then raise exception 'bad_value'; end if;
  select * into pr from public.profiles where regexp_replace(coalesce(phone, ''), '\D', '', 'g') like '%' || right(d, 9) limit 1;
  if not found then raise exception 'profile_not_found'; end if;          -- одам аввал сайтга Telegram орқали кириши керак
  insert into public.admin_users (profile_id, name, roles) values (pr.id, coalesce(nullif(p_name, ''), pr.name, pr.phone), p_roles)
    on conflict (profile_id) do update set roles = excluded.roles, status = 'active' returning admin_users.id into id;
  perform public.admin_log('admin_add', 'admin', id::text, null, jsonb_build_object('roles', p_roles, 'phone', public.mask_phone(pr.phone)));
  return id;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_admin_set(p_code text, p_id bigint, p_roles text[], p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.admin_users;
begin
  perform public.admin_check(p_code); perform public.admin_need('admins');
  select * into a from public.admin_users where id = p_id;
  if not found then raise exception 'unknown_key'; end if;
  if p_id = nullif(current_setting('app.admin_id', true), '')::bigint and (p_status = 'blocked' or not ('owner' = any(p_roles))) then raise exception 'cannot_self'; end if;
  update public.admin_users set roles = coalesce(p_roles, roles), status = coalesce(p_status, status) where id = p_id;
  if p_status = 'blocked' then update public.admin_sessions set ended_at = now() where admin_id = p_id and ended_at is null; end if;
  perform public.admin_log('admin_set', 'admin', p_id::text, jsonb_build_object('roles', a.roles, 'status', a.status), jsonb_build_object('roles', p_roles, 'status', p_status));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_admins(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code); perform public.admin_need('admins');
  return coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'name', a.name, 'phone', p.phone, 'roles', to_jsonb(a.roles), 'status', a.status,
          'pin', a.pin_hash is not null, 'last', (select max(last_seen) from public.admin_sessions s where s.admin_id = a.id)) order by a.id)
          from public.admin_users a join public.profiles p on p.id = a.profile_id), '[]'::jsonb);
end $function$;

CREATE OR REPLACE FUNCTION public.admin_advance(p_code text, p_no bigint, p_max integer)
 RETURNS orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.orders; old_stage int;
begin
  perform public.admin_check(p_code); perform public.admin_need('orders_edit');
  select stage into old_stage from public.orders where no = p_no;
  update public.orders set stage = stage + 1, times = times || to_jsonb((extract(epoch from now()) * 1000)::bigint)
   where no = p_no and stage < p_max returning * into r;
  if found then perform public.admin_log('stage', 'order', p_no::text, jsonb_build_object('stage', old_stage), jsonb_build_object('stage', r.stage)); end if;
  return r;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_alert_scan()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record;
        mp int := coalesce((select value::int from public.app_settings where key = 'payout_alert_minutes'), 5);
        mu int := coalesce((select value::int from public.app_settings where key = 'unpicked_alert_minutes'), 30);
begin
  create temp table if not exists _want (key text, lvl text, text text, order_no bigint) on commit drop;
  delete from _want where true;
  insert into _want
    select 'unpicked:' || o.no, 'red', '🔴 №' || o.no || ': ҳеч ким олмаган (' || (extract(epoch from now() - o.created_at) / 60)::int || ' дақиқа)', o.no
      from public.orders o where o.picker_id is null and o.stage = 0 and o.pay_status in ('paid', 'none')
        and o.created_at < now() - make_interval(mins => mu) and o.created_at > now() - interval '3 days'
    union all
    select 'payout:' || p.id, 'red', '🔴 №' || p.order_no || ': дўконга тўлов кутилмоқда — ' || coalesce(s.shop, s.name, '') || ', ' || p.total || ' сўм', p.order_no
      from public.purchases p left join public.sellers s on s.id = p.shop_id
      where p.status = 'pending' and p.created_at < now() - make_interval(mins => mp)
    union all
    select 'ledger:' || c.order_no, 'red', '🔴 №' || c.order_no || ': пул журнали мувозанатда эмас (фарқ ' || c.diff || ')', c.order_no from public.ledger_check c
    union all
    select 'refund:' || r2.id, 'yellow', '🟡 №' || r2.order_no || ': қайтариш 24 соатдан ортиқ кутмоқда, ' || r2.amount || ' сўм', r2.order_no
      from public.refunds r2 where r2.status = 'pending' and r2.created_at < now() - interval '24 hours'
    union all
    select 'ticket:' || t.id, 'yellow', '🟡 Мурожаат №' || t.id || coalesce(' (буюртма №' || t.order_no || ')', '') || ': жавоб кутмоқда', t.order_no
      from public.tickets t where t.status = 'open' and t.created_at < now() - interval '10 minutes'
    union all
    select 'reg:' || s.id, 'info', 'ℹ️ Янги ариза: ' || s.role || ' — ' || coalesce(nullif(s.shop, ''), s.name), null
      from public.sellers s where s.status = 'pending';
  for r in
    insert into public.admin_alerts (key, lvl, text, order_no)
      select key, lvl, text, order_no from _want on conflict (key) where resolved_at is null do nothing returning text
  loop
    perform public.bot_post(jsonb_build_object('alert', r.text));
  end loop;
  update public.admin_alerts a set resolved_at = now() where a.resolved_at is null and not exists (select 1 from _want w where w.key = a.key);
end $function$;

CREATE OR REPLACE FUNCTION public.admin_alerts_json()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('lvl', case lvl when 'info' then 'info' else lvl end, 'no', order_no, 'text', regexp_replace(text, '^[^ ]+ ', ''), 'key', key)
         order by case lvl when 'red' then 0 when 'yellow' then 1 else 2 end, id), '[]'::jsonb)
  from public.admin_alerts where resolved_at is null
$function$;

CREATE OR REPLACE FUNCTION public.admin_analytics(p_code text, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d int := least(greatest(coalesce(p_days, 30), 7), 180); since timestamptz; r jsonb;
begin
  perform public.admin_check(p_code);
  since := now() - make_interval(days => d);
  select jsonb_build_object(
    'days', d,
    -- Когорта: биринчи тўланган буюртмаси охирги 180 кунда бўлган мижозлар; 30 ва 90 кунда қайта буюртма бергани
    'cohort', (select jsonb_build_object(
        'customers', count(*),
        'repeat30', count(*) filter (where second_at is not null and second_at <= first_at + interval '30 days'),
        'repeat90', count(*) filter (where second_at is not null and second_at <= first_at + interval '90 days'),
        'mature30', count(*) filter (where first_at <= now() - interval '30 days'),
        'mature90', count(*) filter (where first_at <= now() - interval '90 days'),
        'rep30_mature', count(*) filter (where first_at <= now() - interval '30 days' and second_at is not null and second_at <= first_at + interval '30 days'),
        'rep90_mature', count(*) filter (where first_at <= now() - interval '90 days' and second_at is not null and second_at <= first_at + interval '90 days'))
      from (select profile_id, min(created_at) first_at, (array_agg(created_at order by created_at))[2] second_at
              from public.orders where profile_id is not null and pay_status in ('paid', 'none') group by profile_id
              having min(created_at) >= now() - interval '180 days') c),
    -- Бозорлар бўйича
    'markets', coalesce((select jsonb_agg(x order by (x->>'orders')::int desc) from (
        select jsonb_build_object('id', m.id, 'name', coalesce(m.name_uz, m.name), 'orders', count(o.no),
               'avg', coalesce(round(avg(o.total)), 0), 'sum', coalesce(sum(o.total), 0),
               'delivered', count(*) filter (where o.stage >= case o.mode when 'pickup' then 3 else 4 end),
               'missing_pct', (select case when count(*) = 0 then 0 else round(100.0 * count(*) filter (where l.status = 'missing') / count(*), 1) end
                               from public.order_lines l join public.orders o2 on o2.no = l.order_no where o2.market_id = m.id and o2.created_at >= since)) x
          from public.markets m left join public.orders o on o.market_id = m.id and o.created_at >= since and o.pay_status in ('paid', 'none')
         group by m.id) q), '[]'::jsonb),
    -- Тезлик: босқичлар орасидаги ўртача дақиқа (orders.times — ҳар босқичга ўтган вақт, мс)
    'speed', (select jsonb_build_object(
        'n', count(*),
        'to_stage1', round(avg((times->>1)::numeric - (times->>0)::numeric) filter (where jsonb_array_length(times) > 1) / 60000.0, 1),
        'to_stage2', round(avg((times->>2)::numeric - (times->>1)::numeric) filter (where jsonb_array_length(times) > 2) / 60000.0, 1),
        'to_stage3', round(avg((times->>3)::numeric - (times->>2)::numeric) filter (where jsonb_array_length(times) > 3) / 60000.0, 1),
        'to_stage4', round(avg((times->>4)::numeric - (times->>3)::numeric) filter (where jsonb_array_length(times) > 4) / 60000.0, 1),
        'total', round(avg((times->>(jsonb_array_length(times) - 1))::numeric - (times->>0)::numeric) filter (where jsonb_array_length(times) > 1 and stage >= case mode when 'pickup' then 3 else 4 end) / 60000.0, 1),
        'late_pct', round(100.0 * count(*) filter (where jsonb_array_length(times) > 1 and stage >= case mode when 'pickup' then 3 else 4 end
                         and (times->>(jsonb_array_length(times) - 1))::numeric - (times->>0)::numeric > 4 * 3600000) /
                         nullif(count(*) filter (where jsonb_array_length(times) > 1 and stage >= case mode when 'pickup' then 3 else 4 end), 0), 1))
      from public.orders where created_at >= since and pay_status in ('paid', 'none')),
    -- Кунлар бўйича буюртма сони ва айланма (график учун)
    'daily', coalesce((select jsonb_agg(jsonb_build_object('day', to_char(g.day, 'YYYY-MM-DD'), 'n', coalesce(x.n, 0), 'sum', coalesce(x.s, 0)) order by g.day)
        from generate_series(date_trunc('day', now()) - make_interval(days => d - 1), date_trunc('day', now()), interval '1 day') g(day)
        left join (select date_trunc('day', created_at) dd, count(*) n, sum(total) s from public.orders where created_at >= since and pay_status in ('paid', 'none') group by 1) x on x.dd = g.day), '[]'::jsonb)
  ) into r;
  if not public.admin_can('money') then r := jsonb_set(r, '{daily}', coalesce((select jsonb_agg(e - 'sum') from jsonb_array_elements(r->'daily') e), '[]'::jsonb)); end if;
  return r;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_assign(p_code text, p_no bigint, p_role text, p_seller_id bigint, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.orders; s public.sellers; old_id bigint; chat bigint;
begin
  perform public.admin_check(p_code); perform public.admin_need('orders_edit');
  if p_role not in ('picker', 'driver') then raise exception 'bad_value'; end if;
  select * into o from public.orders where no = p_no for update;
  if not found then raise exception 'not_found'; end if;
  old_id := case p_role when 'picker' then o.picker_id else o.driver_id end;
  if p_seller_id is not null then
    select * into s from public.sellers where id = p_seller_id and role = case p_role when 'picker' then 'collector' else 'driver' end and status = 'active';
    if not found then raise exception 'person_not_active'; end if;
  end if;
  if p_role = 'picker' then
    update public.orders set picker_id = p_seller_id,
      picker_info = case when p_seller_id is null then null else jsonb_build_object('name', s.name, 'phone', s.phone) end where no = p_no;
  else
    update public.orders set driver_id = p_seller_id,
      driver_info = case when p_seller_id is null then null else jsonb_build_object('name', s.name, 'phone', s.phone, 'car', coalesce(s.car, '')) end where no = p_no;
  end if;
  perform public.admin_log('assign_' || p_role, 'order', p_no::text, jsonb_build_object('seller_id', old_id), jsonb_build_object('seller_id', p_seller_id), p_reason);
  -- хабар: янгисига «сизга берилди», эскисига «олиб ташланди»
  if p_seller_id is not null and s.tg_chat_id is not null then
    perform public.bot_post(jsonb_build_object('dm', jsonb_build_array(jsonb_build_object('chat_id', s.tg_chat_id,
      'text', '📌 №' || p_no || ' буюртма сизга тайинланди (админ). Кабинетни очинг.'))));
  end if;
  if old_id is not null and old_id is distinct from p_seller_id then
    select tg_chat_id into chat from public.sellers where id = old_id;
    if chat is not null then
      perform public.bot_post(jsonb_build_object('dm', jsonb_build_array(jsonb_build_object('chat_id', chat, 'text', '↩️ №' || p_no || ' буюртма сиздан олинди (админ қарори).'))));
    end if;
  end if;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_audit(p_code text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_q text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code); perform public.admin_need('audit');
  return coalesce((select jsonb_agg(to_jsonb(x)) from (
    select id, at, admin_name, action, object, obj_id, old_value, new_value, reason from public.audit_log
     where p_q is null or p_q = '' or (action || ' ' || coalesce(object, '') || ' ' || coalesce(obj_id, '') || ' ' || coalesce(admin_name, '')) ilike '%' || p_q || '%'
     order by id desc limit least(coalesce(p_limit, 100), 500) offset greatest(coalesce(p_offset, 0), 0)) x), '[]'::jsonb);
end $function$;

CREATE OR REPLACE FUNCTION public.admin_can(p_perm text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
begin perform public.admin_need(p_perm); return true; exception when others then return false; end $function$;

CREATE OR REPLACE FUNCTION public.admin_check(p_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare a public.admin_users; pid bigint := public.my_profile_id(); sid bigint;
begin
  if pid is null or not public.is_admin() then raise exception 'admin_login_required' using errcode = '42501'; end if;
  if p_code is not null then
    select u.* into a from public.admin_sessions s join public.admin_users u on u.id = s.admin_id
     where s.token_hash = encode(extensions.digest(p_code, 'sha256'), 'hex') and s.profile_id = pid and s.ended_at is null
       and s.expires_at > now() and s.last_seen > now() - interval '30 minutes' and u.status = 'active';
    if found then
      update public.admin_sessions set last_seen = now() where token_hash = encode(extensions.digest(p_code, 'sha256'), 'hex');
      perform set_config('app.admin_id', a.id::text, true);
      perform set_config('app.admin_name', a.name, true);
      perform set_config('app.admin_roles', array_to_string(a.roles, ','), true);
      return;
    end if;
  end if;
  -- эски умумий код: фақат ҳали ҳеч ким PIN қўймаган бўлса
  if not exists (select 1 from public.admin_users where pin_hash is not null)
     and p_code is not null and p_code = (select value from public.app_settings where key = 'admin_code') then
    perform set_config('app.admin_id', '0', true); perform set_config('app.admin_name', 'умумий код', true); perform set_config('app.admin_roles', 'owner', true);
    return;
  end if;
  raise exception 'wrong code' using errcode = '28000';
end $function$;

CREATE OR REPLACE FUNCTION public.admin_commissions(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare def numeric := coalesce((select value::numeric from public.app_settings where key = 'seller_commission_pct'), 0);
        n int := coalesce((select value::int from public.app_settings where key = 'commission_free_orders'), 0);
begin
  perform public.admin_check(p_code); perform public.admin_need('payout');
  return jsonb_build_object('default', def, 'free_orders', n, 'can_edit', public.admin_can('settings'),
    'shops', coalesce((select jsonb_agg(x order by x->>'name') from (
      select jsonb_build_object('id', s.id, 'name', coalesce(nullif(s.shop, ''), s.name), 'row', s.row_no, 'status', s.status, 'own', s.commission_pct, 'effective', coalesce(s.commission_pct, def),
             'orders', c.k, 'free_left', case when s.commission_pct is null then greatest(0, n - c.k) else 0 end,
             'gross', coalesce(sum(p.total) filter (where p.status = 'paid'), 0), 'commission', coalesce(sum(p.commission) filter (where p.status = 'paid'), 0)) x
        from public.sellers s
        left join public.purchases p on p.shop_id = s.id
        left join lateral (select count(distinct p2.order_no)::int k from public.purchases p2 where p2.shop_id = s.id and p2.status in ('pending', 'paid')) c on true
       where s.role = 'seller' group by s.id, c.k) q), '[]'::jsonb));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_customer(p_code text, p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ph boolean; r jsonb;
begin
  perform public.admin_check(p_code); ph := public.admin_can('phones');
  select jsonb_build_object(
    'profile', jsonb_build_object('id', p.id, 'name', p.name, 'phone', case when ph then p.phone else public.mask_phone(p.phone) end, 'tags', to_jsonb(p.tags),
                'block_reason', p.block_reason, 'since', p.created_at, 'lang', p.lang),
    'orders', coalesce((select jsonb_agg(jsonb_build_object('no', o.no, 'at', o.created_at, 'total', o.total, 'pay', o.pay_status, 'stage', o.stage, 'mode', o.mode) order by o.no desc)
                        from public.orders o where o.profile_id = p.id), '[]'::jsonb),
    'refunds', (select jsonb_build_object('n', count(*), 'sum', coalesce(sum(f.amount), 0)) from public.refunds f join public.orders o on o.no = f.order_no where o.profile_id = p.id),
    'notes', coalesce((select jsonb_agg(jsonb_build_object('at', n.at, 'who', n.admin_name, 'body', n.body) order by n.id desc) from public.notes n where n.kind = 'customer' and n.ref = p.id::text), '[]'::jsonb)
  ) into r from public.profiles p where p.id = p_id;
  return r;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_customer_set(p_code text, p_id bigint, p_tags text[], p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare old text[];
begin
  perform public.admin_check(p_code); perform public.admin_need('people');
  if not (coalesce(p_tags, '{}') <@ array['vip', 'prorab', 'blacklist']) then raise exception 'bad_value'; end if;
  if 'blacklist' = any(coalesce(p_tags, '{}')) and (p_reason is null or length(trim(p_reason)) < 3) then raise exception 'reason_required'; end if;
  select tags into old from public.profiles where id = p_id;
  if not found then raise exception 'unknown_key'; end if;
  update public.profiles set tags = coalesce(p_tags, '{}'), block_reason = case when 'blacklist' = any(coalesce(p_tags, '{}')) then left(p_reason, 300) else null end where id = p_id;
  perform public.admin_log('customer_tags', 'customer', p_id::text, to_jsonb(old), to_jsonb(coalesce(p_tags, '{}')), p_reason);
end $function$;

CREATE OR REPLACE FUNCTION public.admin_customers(p_code text, p_q text DEFAULT NULL::text, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ph boolean; q text := nullif(trim(coalesce(p_q, '')), ''); d text;
begin
  perform public.admin_check(p_code); ph := public.admin_can('phones');
  d := regexp_replace(coalesce(q, ''), '\D', '', 'g');
  return coalesce((select jsonb_agg(x) from (
    select jsonb_build_object('id', p.id, 'name', p.name, 'phone', case when ph then p.phone else public.mask_phone(p.phone) end, 'tags', to_jsonb(p.tags),
           'since', p.created_at, 'orders', count(o.no), 'paid', count(o.no) filter (where o.pay_status in ('paid', 'none')),
           'spent', coalesce(sum(o.total) filter (where o.pay_status in ('paid', 'none')), 0), 'last', max(o.created_at)) x
      from public.profiles p left join public.orders o on o.profile_id = p.id
     where q is null or p.name ilike '%' || q || '%' or (length(d) >= 4 and regexp_replace(coalesce(p.phone, ''), '\D', '', 'g') like '%' || d || '%')
     group by p.id order by max(o.created_at) desc nulls last, p.id desc
     limit least(greatest(coalesce(p_limit, 100), 1), 300)) s), '[]'::jsonb);
end $function$;

CREATE OR REPLACE FUNCTION public.admin_daily_summary()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t record; pp record; al int; txt text;
begin
  select count(*) n, count(*) filter (where pay_status in ('paid', 'none')) paid, coalesce(sum(total) filter (where pay_status in ('paid', 'none')), 0) s,
         coalesce(sum(platform_income) filter (where pay_status in ('paid', 'none')), 0) inc,
         count(*) filter (where stage >= case mode when 'pickup' then 3 else 4 end and pay_status in ('paid', 'none')) done
    into t from public.orders where created_at >= date_trunc('day', now());
  select count(*) n, coalesce(sum(total), 0) s into pp from public.purchases where status = 'pending';
  select count(*) into al from public.admin_alerts where resolved_at is null and lvl in ('red', 'yellow');
  txt := '📊 Кунлик хулоса' || E'\n' ||
         'Буюртма: ' || t.n || ' (тўланган ' || t.paid || ', етказилган ' || t.done || ')' || E'\n' ||
         'Айланма: ' || t.s || ' сўм' || E'\n' ||
         'Платформа даромади: ' || t.inc || ' сўм' || E'\n' ||
         'Дўконга тўлов кутмоқда: ' || pp.n || ' та (' || pp.s || ' сўм)' || E'\n' ||
         case when al > 0 then '⚠️ Очиқ огоҳлантириш: ' || al else '✅ Муаммо йўқ' end;
  perform public.bot_post(jsonb_build_object('alert', txt));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_dashboard(p_code text, p_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d int := least(greatest(coalesce(p_days, 7), 1), 90); since timestamptz; r jsonb;
begin
  perform public.admin_check(p_code);
  perform public.admin_alert_scan();
  since := now() - make_interval(days => d);
  select jsonb_build_object(
    'days', d,
    'orders', (select jsonb_build_object(
        'total', count(*), 'paid', count(*) filter (where pay_status = 'paid'), 'unpaid', count(*) filter (where pay_status = 'unpaid'),
        'expired', count(*) filter (where pay_status = 'expired'),
        'sum', coalesce(sum(total) filter (where pay_status in ('paid', 'none')), 0),
        'avg', coalesce(round(avg(total) filter (where pay_status in ('paid', 'none'))), 0),
        'delivered', count(*) filter (where stage >= 4),
        'platform', coalesce(sum(platform_income) filter (where pay_status in ('paid', 'none')), 0)) from public.orders where created_at >= since),
    'today', (select jsonb_build_object('orders', count(*), 'paid', count(*) filter (where pay_status in ('paid', 'none')),
        'sum', coalesce(sum(total) filter (where pay_status in ('paid', 'none')), 0)) from public.orders where created_at >= date_trunc('day', now())),
    'by_stage', coalesce((select jsonb_object_agg(stage::text, n) from (select stage, count(*) n from public.orders where pay_status in ('paid', 'none') and stage < 4 group by stage) s), '{}'::jsonb),
    'funnel', coalesce((select jsonb_object_agg(kind, jsonb_build_object('n', n, 'people', p)) from
        (select kind, count(*) n, count(distinct anon) p from public.events where at >= since group by kind) e), '{}'::jsonb),
    'visitors', (select count(distinct anon) from public.events where at >= since),
    'new_customers', (select count(*) from public.profiles where created_at >= since),
    'customers', (select count(*) from public.profiles),
    'searches_empty', coalesce((select jsonb_agg(x) from (select props->>'q' as q, count(*) n from public.events
        where kind = 'search' and at >= since and coalesce((props->>'n')::int, 0) = 0 group by 1 order by 2 desc limit 10) x), '[]'::jsonb),
    'top_searches', coalesce((select jsonb_agg(x) from (select props->>'q' as q, count(*) n from public.events
        where kind = 'search' and at >= since group by 1 order by 2 desc limit 10) x), '[]'::jsonb),
    'refunds_pending', (select count(*) from public.refunds where status = 'pending'),
    'payouts_pending', (select jsonb_build_object('n', count(*), 'sum', coalesce(sum(total), 0), 'oldest_min', coalesce(max((extract(epoch from now() - created_at) / 60)::int), 0))
                        from public.purchases where status = 'pending'),
    'pending_people', (select count(*) from public.sellers where status = 'pending'),
    'alerts', public.admin_alerts_json()
  ) into r;
  if public.admin_can('money') then
    r := r || jsonb_build_object('money', (select jsonb_build_object(
        'in', coalesce(sum(amount) filter (where kind = 'customer_payment'), 0), 'shops', coalesce(-sum(amount) filter (where kind = 'shop_goods'), 0),
        'drivers', coalesce(-sum(amount) filter (where kind = 'driver_pay'), 0), 'collectors', coalesce(-sum(amount) filter (where kind = 'collector_pay'), 0),
        'gateway', coalesce(-sum(amount) filter (where kind = 'gateway_fee'), 0), 'platform', coalesce(-sum(amount) filter (where kind = 'platform_income'), 0),
        'reserve', coalesce(-sum(amount) filter (where kind = 'reserve_hold'), 0), 'refunds', coalesce(sum(amount) filter (where kind = 'refund'), 0),
        'sum_all', coalesce(sum(amount), 0)) from public.ledger));
  else
    r := jsonb_set(r, '{orders}', (r->'orders') - 'sum' - 'avg' - 'platform') ;
    r := jsonb_set(r, '{today}', (r->'today') - 'sum');
  end if;
  return r;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_fleet_assign(p_code text, p_seller bigint, p_fleet bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare old bigint;
begin
  perform public.admin_check(p_code); perform public.admin_need('people');
  select fleet_id into old from public.sellers where id = p_seller and role = 'driver';
  if not found then raise exception 'unknown_key'; end if;
  if p_fleet is not null and not exists (select 1 from public.fleets where id = p_fleet) then raise exception 'unknown_key'; end if;
  update public.sellers set fleet_id = p_fleet where id = p_seller;
  perform public.admin_log('fleet_assign', 'seller', p_seller::text, to_jsonb(old), to_jsonb(p_fleet));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_fleet_save(p_code text, p_id bigint, p_name text, p_market integer, p_phone text, p_active boolean)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare fid bigint;
begin
  perform public.admin_check(p_code); perform public.admin_need('people');
  if nullif(trim(coalesce(p_name, '')), '') is null then raise exception 'bad_value'; end if;
  if p_market is not null and not exists (select 1 from public.markets where id = p_market) then raise exception 'unknown_key'; end if;
  if p_id is null then
    insert into public.fleets (name, market_id, phone, active) values (left(trim(p_name), 80), p_market, left(p_phone, 40), coalesce(p_active, true)) returning id into fid;
    perform public.admin_log('fleet_save', 'fleet', fid::text, null, jsonb_build_object('name', p_name, 'market', p_market));
  else
    update public.fleets set name = left(trim(p_name), 80), market_id = p_market, phone = left(p_phone, 40), active = coalesce(p_active, active) where id = p_id returning id into fid;
    if fid is null then raise exception 'unknown_key'; end if;
    perform public.admin_log('fleet_save', 'fleet', fid::text, null, jsonb_build_object('name', p_name, 'market', p_market, 'active', p_active));
  end if;
  return fid;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_fleets(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code); perform public.admin_need('people');
  return jsonb_build_object(
    'fleets', coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'name', f.name, 'market_id', f.market_id,
              'market', coalesce(m.name_uz, m.name), 'phone', f.phone, 'active', f.active,
              'drivers', (select count(*) from public.sellers s where s.fleet_id = f.id and s.role = 'driver' and s.status = 'active')) order by f.id)
              from public.fleets f left join public.markets m on m.id = f.market_id), '[]'::jsonb),
    'drivers', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'name', coalesce(nullif(s.name, ''), s.shop), 'car', s.car, 'phone', s.phone,
              'status', s.status, 'fleet_id', s.fleet_id) order by s.name) from public.sellers s where s.role = 'driver'), '[]'::jsonb),
    'markets', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'name', coalesce(m.name_uz, m.name)) order by m.id) from public.markets m), '[]'::jsonb));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_list_orders(p_code text)
 RETURNS SETOF orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ph boolean;
begin
  perform public.admin_check(p_code); ph := public.admin_can('phones');
  if ph then return query select * from public.orders order by no desc limit 500; return; end if;
  return query select (jsonb_populate_record(null::public.orders, to_jsonb(o) || jsonb_build_object('phone', public.mask_phone(o.phone), 'address', null))).*
               from public.orders o order by o.no desc limit 500;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_log(p_action text, p_object text, p_id text, p_old jsonb DEFAULT NULL::jsonb, p_new jsonb DEFAULT NULL::jsonb, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.audit_log (admin_id, admin_name, action, object, obj_id, old_value, new_value, reason)
  values (nullif(current_setting('app.admin_id', true), '')::bigint, current_setting('app.admin_name', true), p_action, p_object, p_id, p_old, p_new, left(p_reason, 300));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_login(p_pin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare a public.admin_users; pid bigint := public.my_profile_id(); tok text; ok boolean;
begin
  if pid is null or not public.is_admin() then raise exception 'admin_login_required' using errcode = '42501'; end if;
  select * into a from public.admin_users where profile_id = pid;
  if not found or a.pin_hash is null then raise exception 'pin_not_set'; end if;
  if a.status <> 'active' then raise exception 'blocked'; end if;
  if a.locked_until is not null and a.locked_until > now() then return jsonb_build_object('error', 'locked'); end if;
  ok := a.pin_hash = extensions.crypt(coalesce(p_pin, ''), a.pin_hash);
  if not ok then
    update public.admin_users set failed = failed + 1, locked_until = case when failed + 1 >= 5 then now() + interval '15 minutes' end where id = a.id;
    if a.failed + 1 >= 5 then
      update public.admin_users set failed = 0 where id = a.id;
      perform public.bot_post(jsonb_build_object('alert', '🔐 ' || a.name || ' ҳисобига 5 та нотўғри PIN киритилди, 15 дақиқага блокланди.'));
    end if;
    return jsonb_build_object('error', 'wrong');          -- хато кўтарилмайди: акс ҳолда ҳисоблагич қайтиб кетади
  end if;
  update public.admin_users set failed = 0, locked_until = null where id = a.id;
  tok := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  insert into public.admin_sessions (admin_id, profile_id, token_hash, expires_at)
    values (a.id, pid, encode(extensions.digest(tok, 'sha256'), 'hex'), now() + interval '12 hours');
  perform set_config('app.admin_id', a.id::text, true); perform set_config('app.admin_name', a.name, true);
  perform public.admin_log('login', 'admin', a.id::text);
  return jsonb_build_object('token', tok, 'name', a.name, 'roles', to_jsonb(a.roles));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_logout(p_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  perform public.admin_check(p_code);
  update public.admin_sessions set ended_at = now() where token_hash = encode(extensions.digest(p_code, 'sha256'), 'hex');
  perform public.admin_log('logout', 'admin', current_setting('app.admin_id', true));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_me(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code);
  return jsonb_build_object('id', current_setting('app.admin_id', true), 'name', current_setting('app.admin_name', true),
                            'roles', to_jsonb(string_to_array(current_setting('app.admin_roles', true), ',')));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_need(p_perm text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare r text[] := string_to_array(coalesce(current_setting('app.admin_roles', true), ''), ',');
        ok text[];
begin
  ok := case p_perm
    when 'orders_edit' then array['owner', 'operator']
    when 'money'       then array['owner', 'accountant']
    when 'payout'      then array['owner', 'accountant']
    when 'refund'      then array['owner', 'accountant', 'operator']
    when 'people'      then array['owner', 'operator']
    when 'catalog'     then array['owner', 'operator']
    when 'settings'    then array['owner']
    when 'admins'      then array['owner']
    when 'audit'       then array['owner', 'accountant']
    when 'tickets'     then array['owner', 'operator', 'support']
    when 'phones'      then array['owner', 'operator', 'support']
    else array['owner'] end;
  if not (r && ok) then raise exception 'forbidden:%', p_perm using errcode = '42501'; end if;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_note_add(p_code text, p_kind text, p_ref text, p_body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code);
  if p_kind not in ('order', 'customer', 'seller') or coalesce(trim(p_body), '') = '' or length(p_body) > 1000 then raise exception 'bad_value'; end if;
  insert into public.notes (kind, ref, body, admin_id, admin_name)
    values (p_kind, p_ref, trim(p_body), nullif(current_setting('app.admin_id', true), '')::bigint, current_setting('app.admin_name', true));
  perform public.admin_log('note_add', p_kind, p_ref, null, jsonb_build_object('len', length(p_body)));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_notes(p_code text, p_kind text, p_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code);
  return coalesce((select jsonb_agg(jsonb_build_object('at', n.at, 'who', n.admin_name, 'body', n.body) order by n.id desc) from public.notes n where n.kind = p_kind and n.ref = p_ref), '[]'::jsonb);
end $function$;

CREATE OR REPLACE FUNCTION public.admin_order(p_code text, p_no bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r jsonb; ph boolean; mo boolean;
begin
  perform public.admin_check(p_code); ph := public.admin_can('phones'); mo := public.admin_can('money');
  select jsonb_build_object(
    'order', case when ph then to_jsonb(o) else to_jsonb(o) || jsonb_build_object('phone', public.mask_phone(o.phone), 'address', null) end,
    'lines', coalesce((select jsonb_agg(to_jsonb(l) order by l.line_no) from public.order_lines l where l.order_no = o.no), '[]'::jsonb),
    'purchases', coalesce((select jsonb_agg(to_jsonb(p) || jsonb_build_object('shop_name', (select coalesce(nullif(s.shop, ''), s.name) from public.sellers s where s.id = p.shop_id)) order by p.id)
                           from public.purchases p where p.order_no = o.no), '[]'::jsonb),
    'payments', case when mo then coalesce((select jsonb_agg(to_jsonb(y) order by y.id) from public.payments y where y.order_no = o.no), '[]'::jsonb) else '[]'::jsonb end,
    'refunds', coalesce((select jsonb_agg(to_jsonb(f) order by f.id) from public.refunds f where f.order_no = o.no), '[]'::jsonb),
    'ledger', case when mo then coalesce((select jsonb_agg(jsonb_build_object('kind', g.kind, 'amount', g.amount, 'note', g.note, 'at', g.created_at) order by g.id)
                        from public.ledger g where g.order_no = o.no), '[]'::jsonb) else '[]'::jsonb end,
    'picker', (select s.name from public.sellers s where s.id = o.picker_id),
    'driver', (select s.name from public.sellers s where s.id = o.driver_id),
    'history', coalesce((select jsonb_agg(jsonb_build_object('at', a.at, 'who', a.admin_name, 'action', a.action, 'old', a.old_value, 'new', a.new_value, 'reason', a.reason) order by a.id)
                         from public.audit_log a where a.object = 'order' and a.obj_id = o.no::text), '[]'::jsonb)
  ) into r from public.orders o where o.no = p_no;
  return r;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_payout_decide(p_code text, p_id bigint, p_ok boolean, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p public.purchases;
begin
  perform public.admin_check(p_code); perform public.admin_need('payout');
  select * into p from public.purchases where id = p_id;
  if not found or p.status <> 'pending' then raise exception 'not_pending'; end if;
  if not p_ok and (p_note is null or length(trim(p_note)) < 3) then raise exception 'reason_required'; end if;
  perform public.admin_log(case when p_ok then 'payout_paid' else 'payout_reject' end, 'order', p.order_no::text, null,
                           jsonb_build_object('purchase', p_id, 'total', p.total, 'shop_id', p.shop_id), p_note);
  perform public.bot_post(jsonb_build_object('pay_purchase', jsonb_build_object('id', p_id, 'ok', p_ok)));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_payouts(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code); perform public.admin_need('payout');
  return jsonb_build_object(
    'pending', coalesce((select jsonb_agg(x order by x->>'created_at') from (
        select jsonb_build_object('id', p.id, 'order_no', p.order_no, 'shop', coalesce(nullif(s.shop, ''), s.name), 'row', s.row_no, 'card', s.card, 'phone', s.phone,
               'collector', c.name, 'total', p.total, 'commission', p.commission, 'commission_pct', p.commission_pct, 'net', p.total - p.commission, 'items', p.items, 'created_at', p.created_at,
               'minutes', (extract(epoch from now() - p.created_at) / 60)::int) x
        from public.purchases p left join public.sellers s on s.id = p.shop_id left join public.sellers c on c.id = p.collector_id where p.status = 'pending') q), '[]'::jsonb),
    'recent', coalesce((select jsonb_agg(x order by (x->>'at') desc) from (
        select jsonb_build_object('id', p.id, 'order_no', p.order_no, 'shop', coalesce(nullif(s.shop, ''), s.name), 'total', p.total, 'commission', p.commission, 'net', p.total - p.commission, 'status', p.status,
               'at', coalesce(p.paid_at, p.created_at)) x
        from public.purchases p left join public.sellers s on s.id = p.shop_id where p.status <> 'pending' order by coalesce(p.paid_at, p.created_at) desc limit 30) q), '[]'::jsonb));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_people(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ph boolean;
begin
  perform public.admin_check(p_code); ph := public.admin_can('phones');
  return jsonb_build_object(
    'collectors', coalesce((select jsonb_agg(x order by (x->>'orders')::int desc) from (
        select jsonb_build_object('id', s.id, 'name', s.name, 'phone', case when ph then s.phone else public.mask_phone(s.phone) end, 'status', s.status, 'reason', s.block_reason,
               'orders', count(o.no), 'earned', coalesce(sum(o.collector_fee), 0)) x
        from public.sellers s left join public.orders o on o.picker_id = s.id and o.pay_status in ('paid', 'none')
        where s.role = 'collector' group by s.id) q), '[]'::jsonb),
    'drivers', coalesce((select jsonb_agg(x order by (x->>'orders')::int desc) from (
        select jsonb_build_object('id', s.id, 'name', s.name, 'phone', case when ph then s.phone else public.mask_phone(s.phone) end, 'status', s.status, 'reason', s.block_reason, 'car', s.car,
               'orders', count(o.no), 'earned', coalesce(sum(coalesce(o.delivery_sum, 0) - coalesce(o.driver_fee, 0)), 0)) x
        from public.sellers s left join public.orders o on o.driver_id = s.id and o.pay_status in ('paid', 'none')
        where s.role = 'driver' group by s.id) q), '[]'::jsonb),
    'shops', coalesce((select jsonb_agg(x order by (x->>'sold')::bigint desc) from (
        select jsonb_build_object('id', s.id, 'name', s.name, 'shop', s.shop, 'row', s.row_no, 'status', s.status, 'reason', s.block_reason,
               'phone', case when ph then s.phone else public.mask_phone(s.phone) end, 'card', s.card,
               'prices', (select count(*) from public.offers f where f.seller_id = s.id),
               'sold', coalesce(sum(p.total) filter (where p.status in ('pending', 'paid')), 0), 'paid', coalesce(sum(p.total) filter (where p.status = 'paid'), 0)) x
        from public.sellers s left join public.purchases p on p.shop_id = s.id
        where s.role = 'seller' group by s.id) q), '[]'::jsonb));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_person_set(p_code text, p_id bigint, p_status text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s public.sellers;
begin
  perform public.admin_check(p_code); perform public.admin_need('people');
  if p_status not in ('active', 'blocked', 'pending') then raise exception 'bad_value'; end if;
  if p_status = 'blocked' and (p_reason is null or length(trim(p_reason)) < 3) then raise exception 'reason_required'; end if;
  select * into s from public.sellers where id = p_id and role <> 'admin';
  if not found then raise exception 'unknown_key'; end if;
  update public.sellers set status = p_status, block_reason = case when p_status = 'blocked' then left(p_reason, 300) else null end where id = p_id;
  perform public.admin_log('person_' || p_status, s.role, p_id::text, jsonb_build_object('status', s.status), jsonb_build_object('status', p_status), p_reason);
  if s.tg_chat_id is not null then
    perform public.bot_post(jsonb_build_object('dm', jsonb_build_array(jsonb_build_object('chat_id', s.tg_chat_id,
      'text', case p_status when 'active' then '✅ Аризангиз тасдиқланди. Ботда /start босинг.' when 'blocked' then '⛔ Ҳисобингиз блокланди. Сабаб: ' || coalesce(p_reason, '') else 'ℹ️ Ҳолатингиз ўзгарди.' end))));
  end if;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_price_detail(p_code text, p_product integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code); perform public.admin_need('catalog');
  return jsonb_build_object(
    'offers', coalesce((select jsonb_agg(jsonb_build_object('seller_id', o.seller_id, 'shop', coalesce(nullif(s.shop, ''), s.name), 'row', s.row_no,
                 'price', o.price, 'in_stock', o.in_stock, 'upd', o.updated_at) order by o.price) from public.offers o join public.sellers s on s.id = o.seller_id where o.product_id = p_product), '[]'::jsonb),
    'history', coalesce((select jsonb_agg(jsonb_build_object('at', h.at, 'shop', coalesce(nullif(s.shop, ''), s.name), 'old', h.old_price, 'new', h.new_price, 'src', h.source) order by h.id desc)
                 from (select * from public.price_history where product_id = p_product order by id desc limit 30) h left join public.sellers s on s.id = h.seller_id), '[]'::jsonb));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_price_set(p_code text, p_seller bigint, p_product integer, p_price bigint, p_in_stock boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare old bigint;
begin
  perform public.admin_check(p_code); perform public.admin_need('catalog');
  if p_price is null or p_price <= 0 or p_price > 1000000000 then raise exception 'bad_value'; end if;
  if not exists (select 1 from public.sellers where id = p_seller and role = 'seller') then raise exception 'unknown_key'; end if;
  if not exists (select 1 from public.products where id = p_product) then raise exception 'unknown_key'; end if;
  select price into old from public.offers where seller_id = p_seller and product_id = p_product;
  insert into public.offers (seller_id, product_id, price, in_stock, updated_at) values (p_seller, p_product, p_price, coalesce(p_in_stock, true), now())
    on conflict (seller_id, product_id) do update set price = excluded.price, in_stock = excluded.in_stock, updated_at = now();
  insert into public.price_history (seller_id, product_id, old_price, new_price, source, admin_id)
    values (p_seller, p_product, old, p_price, 'admin', nullif(current_setting('app.admin_id', true), '')::bigint);
  perform public.admin_log('price_set', 'price', p_seller || ':' || p_product, to_jsonb(old), to_jsonb(p_price));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_prices(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare stale int := coalesce((select value::int from public.app_settings where key = 'price_stale_days'), 3);
        dev numeric := coalesce((select value::numeric from public.app_settings where key = 'price_dev_pct'), 30);
begin
  perform public.admin_check(p_code); perform public.admin_need('catalog');
  return jsonb_build_object(
    'stale_days', stale, 'dev_pct', dev,
    'shops', coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'name', coalesce(nullif(s.shop, ''), s.name), 'row', s.row_no, 'status', s.status,
                'prices', (select count(*) from public.offers o where o.seller_id = s.id)) order by coalesce(nullif(s.shop, ''), s.name))
              from public.sellers s where s.role = 'seller'), '[]'::jsonb),
    'products', coalesce((select jsonb_agg(x order by x->>'cat', x->>'name') from (
        select jsonb_build_object('id', p.id, 'cat', p.cat, 'name', p.name, 'spec', p.spec, 'unit', p.unit, 'base', p.base_price, 'active', p.active,
          'n', count(o.seller_id) filter (where o.in_stock),
          'min', min(o.price) filter (where o.in_stock), 'max', max(o.price) filter (where o.in_stock),
          'med', (percentile_cont(0.5) within group (order by o.price) filter (where o.in_stock))::bigint,
          'upd', max(o.updated_at),
          'old', count(o.seller_id) filter (where o.in_stock and o.updated_at < now() - make_interval(days => stale)),
          'dev', count(o.seller_id) filter (where o.in_stock and o.price > 0 and exists (
                   select 1 from (select percentile_cont(0.5) within group (order by o2.price) m from public.offers o2 where o2.product_id = p.id and o2.in_stock) mm
                   where mm.m > 0 and abs(o.price - mm.m) * 100 > dev * mm.m))) x
        from public.products p left join public.offers o on o.product_id = p.id group by p.id) q), '[]'::jsonb));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_prices_apply(p_code text, p_seller bigint, p_rows jsonb, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int := 0; skipped int := 0; r record; aid bigint := nullif(current_setting('app.admin_id', true), '')::bigint;
begin
  perform public.admin_check(p_code); perform public.admin_need('catalog');
  if jsonb_typeof(p_rows) <> 'array' then raise exception 'bad_value'; end if;
  if jsonb_array_length(p_rows) > 2000 then raise exception 'too_many_rows'; end if;
  if not exists (select 1 from public.sellers where id = p_seller and role = 'seller') then raise exception 'unknown_key'; end if;
  for r in
    select distinct on (pid) pid, price from (
      select nullif(e.v->>'product_id', '')::int pid,
             case when (e.v->>'price') ~ '^[0-9]+(\.[0-9]+)?$' then round((e.v->>'price')::numeric)::bigint end price, e.ord
      from jsonb_array_elements(p_rows) with ordinality e(v, ord)) t
    where pid is not null order by pid, ord desc
  loop
    if r.price is null or r.price <= 0 or r.price > 1000000000 or not exists (select 1 from public.products where id = r.pid) then skipped := skipped + 1; continue; end if;
    insert into public.price_history (seller_id, product_id, old_price, new_price, source, admin_id)
      select p_seller, r.pid, o.price, r.price, 'excel', aid from (select 1) x left join public.offers o on o.seller_id = p_seller and o.product_id = r.pid;
    insert into public.offers (seller_id, product_id, price, in_stock, updated_at) values (p_seller, r.pid, r.price, true, now())
      on conflict (seller_id, product_id) do update set price = excluded.price, in_stock = true, updated_at = now();
    n := n + 1;
  end loop;
  perform public.admin_log('prices_upload', 'seller', p_seller::text, null, jsonb_build_object('saved', n, 'skipped', skipped), p_note);
  return jsonb_build_object('saved', n, 'skipped', skipped);
end $function$;

CREATE OR REPLACE FUNCTION public.admin_prices_preview(p_code text, p_seller bigint, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare dev numeric := coalesce((select value::numeric from public.app_settings where key = 'price_dev_pct'), 30); res jsonb;
begin
  perform public.admin_check(p_code); perform public.admin_need('catalog');
  if jsonb_typeof(p_rows) <> 'array' then raise exception 'bad_value'; end if;
  if jsonb_array_length(p_rows) > 2000 then raise exception 'too_many_rows'; end if;
  if not exists (select 1 from public.sellers where id = p_seller and role = 'seller') then raise exception 'unknown_key'; end if;
  select coalesce(jsonb_agg(r order by (r->>'line')::int), '[]'::jsonb) into res from (
    select jsonb_build_object('line', t.ord, 'product_id', t.pid, 'name', p.name, 'unit', p.unit, 'price', t.price, 'old', o.price,
             'med', m.med, 'pct', case when o.price > 0 then round((t.price - o.price) * 100.0 / o.price, 1) end,
             'dev', case when m.med > 0 and t.price > 0 then round((t.price - m.med) * 100.0 / m.med, 1) end,
             'st', case when p.id is null then 'err_product' when t.price is null or t.price <= 0 or t.price > 1000000000 then 'err_price'
                        when m.med > 0 and abs(t.price - m.med) * 100 > dev * m.med then 'warn' else 'ok' end) r
    from (select e.ord, nullif(e.v->>'product_id', '')::int pid,
                 case when (e.v->>'price') ~ '^[0-9]+(\.[0-9]+)?$' then round((e.v->>'price')::numeric)::bigint end price
          from jsonb_array_elements(p_rows) with ordinality e(v, ord)) t
    left join public.products p on p.id = t.pid
    left join public.offers o on o.seller_id = p_seller and o.product_id = t.pid
    left join lateral (select (percentile_cont(0.5) within group (order by o2.price))::bigint med from public.offers o2
                       where o2.product_id = t.pid and o2.in_stock and o2.seller_id <> p_seller) m on true) z;
  return res;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_recon(p_code text, p_provider text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare res jsonb; d1 date; d2 date;
begin
  perform public.admin_check(p_code); perform public.admin_need('money');
  if p_provider not in ('click', 'payme') or jsonb_typeof(p_rows) <> 'array' then raise exception 'bad_value'; end if;
  if jsonb_array_length(p_rows) > 5000 then raise exception 'too_many_rows'; end if;
  create temp table if not exists _rc (id text, amount bigint, order_no bigint, d date) on commit drop;
  delete from _rc where true;
  insert into _rc select nullif(trim(e.v->>'id'), ''),
        case when (e.v->>'amount') ~ '^[0-9]+(\.[0-9]+)?$' then round((e.v->>'amount')::numeric)::bigint end,
        case when (e.v->>'order_no') ~ '^[0-9]+$' then (e.v->>'order_no')::bigint end,
        case when (e.v->>'date') ~ '^\d{4}-\d{2}-\d{2}' then left(e.v->>'date', 10)::date end
    from jsonb_array_elements(p_rows) e(v);
  select min(d), max(d) into d1, d2 from _rc;
  if d1 is null then d1 := current_date - 31; d2 := current_date; end if;
  select jsonb_build_object(
    'rows', (select count(*) from _rc), 'from', d1, 'to', d2,
    'ok', (select count(*) from _rc r join public.payments p on p.provider = p_provider and p.status = 'paid' and (p.provider_trans_id = r.id or (r.order_no is not null and p.order_no = r.order_no)) and p.amount = r.amount),
    'amount_diff', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'order_no', p.order_no, 'theirs', r.amount, 'ours', p.amount) order by p.order_no)
        from _rc r join public.payments p on p.provider = p_provider and p.status = 'paid' and (p.provider_trans_id = r.id or (r.order_no is not null and p.order_no = r.order_no)) where p.amount <> r.amount), '[]'::jsonb),
    'only_theirs', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'order_no', r.order_no, 'amount', r.amount, 'date', r.d) order by r.d, r.id)
        from _rc r where not exists (select 1 from public.payments p where p.provider = p_provider and p.status = 'paid' and (p.provider_trans_id = r.id or (r.order_no is not null and p.order_no = r.order_no)))), '[]'::jsonb),
    'only_ours', coalesce((select jsonb_agg(jsonb_build_object('order_no', p.order_no, 'id', p.provider_trans_id, 'amount', p.amount, 'at', p.paid_at) order by p.paid_at)
        from public.payments p where p.provider = p_provider and p.status = 'paid' and p.paid_at::date between d1 and d2
         and not exists (select 1 from _rc r where r.id = p.provider_trans_id or (r.order_no is not null and r.order_no = p.order_no))), '[]'::jsonb))
    into res;
  perform public.admin_log('recon_run', 'provider', p_provider, null, jsonb_build_object('rows', jsonb_array_length(p_rows), 'only_theirs', jsonb_array_length(res->'only_theirs'), 'only_ours', jsonb_array_length(res->'only_ours'), 'amount_diff', jsonb_array_length(res->'amount_diff')));
  return res;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_refund_create(p_code text, p_no bigint, p_kind text, p_amount bigint, p_reason text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.orders; rid bigint; held bigint; done_sum bigint; lim bigint;
begin
  perform public.admin_check(p_code); perform public.admin_need('refund');
  if not public.admin_can('money') then
    lim := coalesce((select value::bigint from public.app_settings where key = 'operator_refund_limit'), 200000);
    if p_amount > lim then raise exception 'over_limit'; end if;
  end if;
  if p_reason is null or length(trim(p_reason)) < 3 then raise exception 'reason_required'; end if;
  select * into o from public.orders where no = p_no;
  if not found or o.pay_status <> 'paid' then raise exception 'not_paid'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'bad_amount'; end if;
  select coalesce(sum(amount), 0) into done_sum from public.refunds where order_no = p_no;
  if done_sum + p_amount > o.pay_amount then raise exception 'too_much'; end if;
  if p_kind = 'reserve' then
    select coalesce(-sum(amount), 0) into held from public.ledger where order_no = p_no and kind = 'reserve_hold';
    if p_amount > held then raise exception 'reserve_too_much'; end if;
  end if;
  insert into public.refunds (order_no, kind, amount, reason, created_by) values (p_no, p_kind, p_amount, left(p_reason, 300), nullif(current_setting('app.admin_id', true), '')::bigint) returning id into rid;
  perform public.admin_log('refund_create', 'order', p_no::text, null, jsonb_build_object('kind', p_kind, 'amount', p_amount, 'refund', rid), p_reason);
  return rid;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_refund_done(p_code text, p_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rf public.refunds; me bigint; lim bigint;
begin
  perform public.admin_check(p_code); perform public.admin_need('payout');
  me := nullif(current_setting('app.admin_id', true), '')::bigint;
  select * into rf from public.refunds where id = p_id for update;
  if not found or rf.status = 'done' then raise exception 'not_pending'; end if;
  lim := coalesce((select value::bigint from public.app_settings where key = 'refund_confirm_limit'), 1000000);
  if rf.amount > lim and rf.created_by is not distinct from me and (select count(*) from public.admin_users where status = 'active' and pin_hash is not null) > 1 then
    raise exception 'second_approval';                                   -- катта сумма: яратган одамдан бошқаси тасдиқлайди
  end if;
  update public.refunds set status = 'done', done_at = now(), done_by = me where id = p_id;
  if rf.kind = 'reserve' then
    insert into public.ledger (order_no, kind, amount, note) values (rf.order_no, 'refund', rf.amount, 'захирадан чиқарилди');
  elsif rf.kind = 'item' then
    insert into public.ledger (order_no, kind, amount, note) values (rf.order_no, 'refund', rf.amount, 'дўконга камроқ тўланади');
  else
    insert into public.ledger (order_no, kind, amount, note) values (rf.order_no, 'refund', rf.amount, 'платформа ҳисобидан');
  end if;
  insert into public.ledger (order_no, kind, amount, note) values (rf.order_no, 'refund', -rf.amount, 'мижозга қайтарилди');
  perform public.admin_log('refund_done', 'order', rf.order_no::text, null, jsonb_build_object('refund', p_id, 'amount', rf.amount));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_refunds(p_code text)
 RETURNS SETOF refunds
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code);
  return query select * from public.refunds order by id desc limit 200;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_release_payout(p_code text, p_no bigint, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code); perform public.admin_need('payout');
  if nullif(trim(coalesce(p_reason, '')), '') is null then raise exception 'reason_required'; end if;
  update public.orders set payout_release = true where no = p_no and not payout_release;
  if not found then raise exception 'unknown_key'; end if;
  perform public.admin_log('payout_release', 'order', p_no::text, null, to_jsonb(true), p_reason);
end $function$;

CREATE OR REPLACE FUNCTION public.admin_revert_setting(p_code text, p_audit_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.audit_log; cur jsonb;
begin
  perform public.admin_check(p_code); perform public.admin_need('settings');
  select * into a from public.audit_log where id = p_audit_id and action in ('set_fee', 'set_tariff', 'set_provider', 'set_app');
  if not found then raise exception 'unknown_key'; end if;
  if a.old_value is null or a.old_value = 'null'::jsonb then raise exception 'cannot_revert'; end if;
  if exists (select 1 from public.audit_log r where r.action = 'revert' and r.obj_id = a.id::text) then raise exception 'not_pending'; end if;
  if a.action = 'set_fee' then
    select to_jsonb(value) into cur from public.fee_settings where key = a.obj_id;
    update public.fee_settings set value = (a.old_value #>> '{}')::numeric where key = a.obj_id;
  elsif a.action = 'set_tariff' then
    select jsonb_build_object('near', near_price, 'mid', mid_price, 'far', far_price) into cur from public.delivery_tariffs where id = a.obj_id;
    update public.delivery_tariffs set near_price = (a.old_value->>'near')::bigint, mid_price = (a.old_value->>'mid')::bigint, far_price = (a.old_value->>'far')::bigint where id = a.obj_id;
  elsif a.action = 'set_provider' then
    select jsonb_build_object('pct', pct, 'enabled', enabled) into cur from public.payment_providers where code = a.obj_id;
    update public.payment_providers set pct = (a.old_value->>'pct')::numeric, enabled = (a.old_value->>'enabled')::boolean where code = a.obj_id;
  else
    select to_jsonb(value) into cur from public.app_settings where key = a.obj_id;
    update public.app_settings set value = a.old_value #>> '{}' where key = a.obj_id;
  end if;
  perform public.admin_log('revert', 'setting', a.id::text, cur, a.old_value, a.action || ' ' || coalesce(a.obj_id, ''));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_set_app(p_code text, p_key text, p_value text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare old text;
begin
  perform public.admin_check(p_code); perform public.admin_need('settings');
  if p_key not in ('pay_minutes', 'reserve_pct', 'answer_minutes', 'payout_alert_minutes', 'unpicked_alert_minutes') then raise exception 'not_allowed'; end if;
  if p_value !~ '^[0-9]{1,3}$' or p_value::int < 1 then raise exception 'bad_value'; end if;
  if p_key = 'reserve_pct' and p_value::int > 30 then raise exception 'bad_value'; end if;
  if p_key = 'pay_minutes' and p_value::int > 180 then raise exception 'bad_value'; end if;
  select value into old from public.app_settings where key = p_key;
  update public.app_settings set value = p_value where key = p_key;
  if not found then insert into public.app_settings (key, value) values (p_key, p_value); end if;
  perform public.admin_log('set_app', 'setting', p_key, to_jsonb(old), to_jsonb(p_value));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_set_commission(p_code text, p_seller bigint, p_pct numeric, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare old numeric;
begin
  perform public.admin_check(p_code); perform public.admin_need('settings');
  if p_seller is null then
    if p_pct is null or p_pct < 0 or p_pct > 30 then raise exception 'bad_value'; end if;
    select value::numeric into old from public.app_settings where key = 'seller_commission_pct';
    update public.app_settings set value = p_pct::text where key = 'seller_commission_pct';
    if not found then insert into public.app_settings (key, value) values ('seller_commission_pct', p_pct::text); end if;
    perform public.admin_log('set_commission', 'setting', 'seller_commission_pct', to_jsonb(old), to_jsonb(p_pct), p_reason);
  else
    if p_pct is not null and (p_pct < 0 or p_pct > 30) then raise exception 'bad_value'; end if;
    select commission_pct into old from public.sellers where id = p_seller and role = 'seller';
    if not found then raise exception 'unknown_key'; end if;
    update public.sellers set commission_pct = p_pct where id = p_seller;
    perform public.admin_log('set_commission', 'seller', p_seller::text, to_jsonb(old), to_jsonb(p_pct), p_reason);
  end if;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_set_commission_free(p_code text, p_n integer, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare old text;
begin
  perform public.admin_check(p_code); perform public.admin_need('settings');
  if p_n is null or p_n < 0 or p_n > 1000 then raise exception 'bad_value'; end if;
  select value into old from public.app_settings where key = 'commission_free_orders';
  update public.app_settings set value = p_n::text where key = 'commission_free_orders';
  if not found then insert into public.app_settings (key, value) values ('commission_free_orders', p_n::text); end if;
  perform public.admin_log('set_commission_free', 'setting', 'commission_free_orders', to_jsonb(old), to_jsonb(p_n), p_reason);
end $function$;

CREATE OR REPLACE FUNCTION public.admin_set_fee(p_code text, p_key text, p_value numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare old numeric;
begin
  perform public.admin_check(p_code); perform public.admin_need('settings');
  if p_value is null or p_value < 0 or p_value > 100000000 then raise exception 'bad_value'; end if;
  select value into old from public.fee_settings where key = p_key and key <> 'cfg_v2';
  if not found then raise exception 'unknown_key'; end if;
  update public.fee_settings set value = p_value where key = p_key;
  perform public.admin_log('set_fee', 'fee', p_key, to_jsonb(old), to_jsonb(p_value));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_set_pin(p_code text, p_pin text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare a public.admin_users; pid bigint := public.my_profile_id(); nm text;
begin
  if pid is null or not public.is_admin() then raise exception 'admin_login_required' using errcode = '42501'; end if;
  if p_pin is null or p_pin !~ '^[0-9]{6,12}$' then raise exception 'bad_pin'; end if;
  select * into a from public.admin_users where profile_id = pid;
  if found and a.pin_hash is null then
    update public.admin_users set pin_hash = extensions.crypt(p_pin, extensions.gen_salt('bf', 8)) where id = a.id;
  elsif found then
    perform public.admin_check(p_code);                                   -- PIN алмаштириш: жорий сессия керак
    update public.admin_users set pin_hash = extensions.crypt(p_pin, extensions.gen_salt('bf', 8)) where id = a.id;
  else
    if p_code is distinct from (select value from public.app_settings where key = 'admin_code') then raise exception 'wrong code' using errcode = '28000'; end if;
    select coalesce(name, phone, 'Эга') into nm from public.profiles where id = pid;
    insert into public.admin_users (profile_id, name, roles, pin_hash) values (pid, nm, array['owner'], extensions.crypt(p_pin, extensions.gen_salt('bf', 8)));
  end if;
  perform set_config('app.admin_name', coalesce(nm, a.name, ''), true);
  perform public.admin_log('set_pin', 'admin', coalesce(a.id::text, pid::text));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_set_provider(p_code text, p_pcode text, p_pct numeric, p_enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.payment_providers;
begin
  perform public.admin_check(p_code); perform public.admin_need('settings');
  if p_pct is null or p_pct < 0 or p_pct > 10 then raise exception 'bad_value'; end if;
  select * into t from public.payment_providers where code = p_pcode;
  if not found then raise exception 'unknown_key'; end if;
  update public.payment_providers set pct = p_pct, enabled = coalesce(p_enabled, enabled) where code = p_pcode;
  perform public.admin_log('set_provider', 'provider', p_pcode, jsonb_build_object('pct', t.pct, 'enabled', t.enabled), jsonb_build_object('pct', p_pct, 'enabled', coalesce(p_enabled, t.enabled)));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_set_tariff(p_code text, p_id text, p_near bigint, p_mid bigint, p_far bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.delivery_tariffs;
begin
  perform public.admin_check(p_code); perform public.admin_need('settings');
  if least(p_near, p_mid, p_far) <= 0 or greatest(p_near, p_mid, p_far) > 5000000 then raise exception 'bad_value'; end if;
  select * into t from public.delivery_tariffs where id = p_id;
  if not found then raise exception 'unknown_key'; end if;
  update public.delivery_tariffs set near_price = p_near, mid_price = p_mid, far_price = p_far where id = p_id;
  perform public.admin_log('set_tariff', 'tariff', p_id, jsonb_build_object('near', t.near_price, 'mid', t.mid_price, 'far', t.far_price), jsonb_build_object('near', p_near, 'mid', p_mid, 'far', p_far));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_settings(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code);
  return jsonb_build_object(
    'fees', coalesce((select jsonb_agg(jsonb_build_object('key', key, 'value', value, 'note', note) order by key) from public.fee_settings where key <> 'cfg_v2'), '[]'::jsonb),
    'tariffs', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'name', name, 'cap', cap_kg, 'near', near_price, 'mid', mid_price, 'far', far_price, 'active', active) order by sort) from public.delivery_tariffs), '[]'::jsonb),
    'providers', coalesce((select jsonb_agg(jsonb_build_object('code', code, 'name', name, 'pct', pct, 'enabled', enabled) order by sort) from public.payment_providers), '[]'::jsonb),
    'app', coalesce((select jsonb_object_agg(key, value) from public.app_settings where key in ('pay_minutes', 'reserve_pct', 'payments_on', 'pay_test_mode', 'answer_minutes', 'payout_alert_minutes', 'unpicked_alert_minutes')), '{}'::jsonb),
    'can_edit', public.admin_can('settings'));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_settings_history(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code); perform public.admin_need('settings');
  return coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'at', a.at, 'who', a.admin_name, 'action', a.action, 'key', a.obj_id, 'old', a.old_value, 'new', a.new_value,
            'reverted', exists (select 1 from public.audit_log r where r.action = 'revert' and r.obj_id = a.id::text)) order by a.id desc)
          from (select * from public.audit_log where action in ('set_fee', 'set_tariff', 'set_provider', 'set_app') order by id desc limit 60) a), '[]'::jsonb);
end $function$;

CREATE OR REPLACE FUNCTION public.admin_staff(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code); perform public.admin_need('payout');
  return jsonb_build_object(
    'people', coalesce((select jsonb_agg(jsonb_build_object('id', b.seller_id, 'role', b.role, 'name', b.name, 'phone', b.phone, 'card', b.card, 'status', b.status,
               'earned', b.earned, 'paid', b.paid, 'due', b.earned - b.paid, 'orders', b.orders, 'waiting', b.waiting, 'held', b.held) order by (b.earned - b.paid) desc, b.name) from public.staff_balance_v b
               where b.earned > 0 or b.paid > 0 or b.waiting > 0 or b.held > 0), '[]'::jsonb),
    'held_orders', coalesce((select jsonb_agg(jsonb_build_object('no', o.no, 'note', o.received_note, 'at', o.received_at) order by o.no desc)
               from public.orders o where o.received_ok is false and not o.payout_release and o.pay_status in ('paid', 'none')), '[]'::jsonb),
    'recent', coalesce((select jsonb_agg(jsonb_build_object('at', x.at, 'name', x.name, 'role', x.role, 'amount', x.amount, 'note', x.note) order by x.id desc) from (
               select p.id, p.at, coalesce(nullif(s.name, ''), s.shop) as name, s.role, p.amount, p.note from public.staff_payouts p join public.sellers s on s.id = p.seller_id
               order by p.id desc limit 30) x), '[]'::jsonb));
end $function$;

CREATE OR REPLACE FUNCTION public.admin_staff_pay(p_code text, p_seller bigint, p_amount bigint, p_note text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare due bigint; pid bigint;
begin
  perform public.admin_check(p_code); perform public.admin_need('payout');
  if p_amount is null or p_amount <= 0 then raise exception 'bad_amount'; end if;
  perform 1 from public.sellers where id = p_seller and role in ('collector', 'driver') for update;      -- такрорий босишдан ҳимоя
  if not found then raise exception 'unknown_key'; end if;
  select earned - paid into due from public.staff_balance_v where seller_id = p_seller;
  if p_amount > coalesce(due, 0) then raise exception 'over_balance'; end if;
  insert into public.staff_payouts (seller_id, amount, note, admin_id) values (p_seller, p_amount, left(p_note, 200), nullif(current_setting('app.admin_id', true), '')::bigint) returning id into pid;
  perform public.admin_log('staff_pay', 'seller', p_seller::text, jsonb_build_object('due', due), jsonb_build_object('paid', p_amount), p_note);
  perform public.bot_post(jsonb_build_object('dm', jsonb_build_array(jsonb_build_object('chat_id', (select tg_chat_id from public.sellers where id = p_seller),
          'text', '💸 Сизга ' || p_amount || ' сўм тўланди. Раҳмат!'))))
    where (select tg_chat_id from public.sellers where id = p_seller) is not null;
  return pid;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_ticket(p_code text, p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r jsonb;
begin
  perform public.admin_check(p_code); perform public.admin_need('tickets');
  select jsonb_build_object('ticket', to_jsonb(t) - 'profile_id', 'customer', jsonb_build_object('id', p.id, 'name', p.name, 'phone', case when public.admin_can('phones') then p.phone else public.mask_phone(p.phone) end),
      'order', (select jsonb_build_object('no', o.no, 'total', o.total, 'pay', o.pay_status, 'pay_amount', o.pay_amount, 'stage', o.stage, 'mode', o.mode, 'received_ok', o.received_ok, 'received_note', o.received_note) from public.orders o where o.no = t.order_no),
      'msgs', coalesce((select jsonb_agg(jsonb_build_object('from', m.from_role, 'who', m.admin_name, 'body', m.body, 'at', m.at) order by m.id) from public.ticket_msgs m where m.ticket_id = t.id), '[]'::jsonb))
    into r from public.tickets t join public.profiles p on p.id = t.profile_id where t.id = p_id;
  return r;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_ticket_close(p_code text, p_id bigint, p_decision text, p_amount bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.tickets; rid bigint; tg bigint; msg text;
begin
  perform public.admin_check(p_code); perform public.admin_need('tickets');
  if p_decision not in ('accept', 'partial', 'reject') then raise exception 'bad_value'; end if;
  if p_note is null or length(trim(p_note)) < 3 then raise exception 'reason_required'; end if;
  select * into t from public.tickets where id = p_id for update;
  if not found or t.status = 'closed' then raise exception 'not_pending'; end if;
  if p_decision <> 'reject' then
    if t.order_no is null then raise exception 'order_required'; end if;
    if p_amount is null or p_amount <= 0 then raise exception 'bad_amount'; end if;
    rid := public.admin_refund_create(p_code, t.order_no, 'other', p_amount, 'мурожаат №' || p_id || ': ' || p_note);
  end if;
  update public.tickets set status = 'closed', decision = p_decision, decision_amount = case when p_decision = 'reject' then null else p_amount end,
         closed_at = now(), closed_by = nullif(current_setting('app.admin_id', true), '')::bigint where id = p_id;
  msg := case p_decision when 'accept' then 'Мурожаатингиз маъқулланди, ' || p_amount || ' сўм қайтарилади.' when 'partial' then 'Мурожаатингиз қисман маъқулланди, ' || p_amount || ' сўм қайтарилади.' else 'Мурожаатингиз кўриб чиқилди, асос топилмади.' end
         || ' ' || trim(p_note);
  insert into public.ticket_msgs (ticket_id, from_role, body, admin_name) values (p_id, 'admin', msg, current_setting('app.admin_name', true));
  perform public.admin_log('ticket_close', 'ticket', p_id::text, null, jsonb_build_object('decision', p_decision, 'amount', p_amount, 'refund', rid), p_note);
  select tg_id into tg from public.profiles where id = t.profile_id;
  if tg is not null then perform public.bot_post(jsonb_build_object('dm', jsonb_build_array(jsonb_build_object('chat_id', tg, 'text', '💬 Ta''mir: ' || msg)))); end if;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_ticket_count(p_code text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code);
  if not public.admin_can('tickets') then return 0; end if;
  return (select count(*) from public.tickets where status = 'open');
end $function$;

CREATE OR REPLACE FUNCTION public.admin_ticket_reply(p_code text, p_id bigint, p_body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t public.tickets; tg bigint;
begin
  perform public.admin_check(p_code); perform public.admin_need('tickets');
  if coalesce(trim(p_body), '') = '' or length(p_body) > 1000 then raise exception 'bad_value'; end if;
  select * into t from public.tickets where id = p_id for update;
  if not found or t.status = 'closed' then raise exception 'not_pending'; end if;
  insert into public.ticket_msgs (ticket_id, from_role, body, admin_name) values (p_id, 'admin', trim(p_body), current_setting('app.admin_name', true));
  update public.tickets set status = 'answered' where id = p_id;
  perform public.admin_log('ticket_reply', 'ticket', p_id::text, null, jsonb_build_object('len', length(p_body)));
  select tg_id into tg from public.profiles where id = t.profile_id;
  if tg is not null then
    perform public.bot_post(jsonb_build_object('dm', jsonb_build_array(jsonb_build_object('chat_id', tg, 'text', '💬 Ta''mir: ' || trim(p_body)))));
  end if;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_tickets(p_code text, p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.admin_check(p_code); perform public.admin_need('tickets');
  return coalesce((select jsonb_agg(x order by (x->>'prio')::int, x->>'at' desc) from (
    select jsonb_build_object('id', t.id, 'order_no', t.order_no, 'status', t.status, 'decision', t.decision, 'at', t.created_at, 'prio', case t.status when 'open' then 0 when 'answered' then 1 else 2 end,
           'name', p.name, 'phone', case when public.admin_can('phones') then p.phone else public.mask_phone(p.phone) end,
           'last', (select left(m.body, 120) from public.ticket_msgs m where m.ticket_id = t.id order by m.id desc limit 1),
           'last_from', (select m.from_role from public.ticket_msgs m where m.ticket_id = t.id order by m.id desc limit 1)) x
      from public.tickets t join public.profiles p on p.id = t.profile_id
     where p_status is null or t.status = p_status order by t.id desc limit 200) q), '[]'::jsonb);
end $function$;

CREATE OR REPLACE FUNCTION public.audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin raise exception 'audit_log is append-only'; end $function$;

CREATE OR REPLACE FUNCTION public.bot_post(p_body jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform net.http_post(
    url     := (select value from public.app_settings where key = 'bot_url'),
    body    := p_body,
    headers := jsonb_build_object('Content-Type', 'application/json',
                                  'x-bot-secret', (select value from public.app_settings where key = 'bot_secret')));
end $function$;

CREATE OR REPLACE FUNCTION public.bot_tick()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare lim interval := make_interval(mins => coalesce((select value::int from public.app_settings where key = 'answer_minutes'), 5));
begin
  if exists (select 1 from public.order_lines where status = 'offered' and offered_at < now() - lim and msg_id is not null)
     or exists (select 1 from public.orders where picker_id is null and alerted_at is null and stage = 0
                and notified_at < now() - lim and notified_at > now() - interval '1 day') then
    perform public.bot_post('{"tick": true}'::jsonb);
  end if;
end $function$;

CREATE OR REPLACE FUNCTION public.col_login_check(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare r public.collector_login; s text; nm text;
begin
  select * into r from public.collector_login where token = p_token;
  if not found or r.created_at < now() - interval '30 minutes' or r.used_at is not null then return jsonb_build_object('status', 'expired'); end if;
  if r.seller_id is null then return jsonb_build_object('status', 'wait'); end if;
  s := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  insert into public.collector_sessions (token_hash, seller_id) values (encode(digest(s, 'sha256'), 'hex'), r.seller_id);
  update public.collector_login set used_at = now() where token = p_token;
  select coalesce(nullif(name, ''), shop) into nm from public.sellers where id = r.seller_id;
  return jsonb_build_object('status', 'ok', 'session', s, 'name', nm);
end $function$;

CREATE OR REPLACE FUNCTION public.col_login_new()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare t text := replace(gen_random_uuid()::text, '-', '');
begin
  delete from public.collector_login where created_at < now() - interval '1 day';
  insert into public.collector_login (token) values (t);
  return t;
end $function$;

CREATE OR REPLACE FUNCTION public.create_order(p jsonb)
 RETURNS orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_pid bigint := public.my_profile_id();
  v_mode text := coalesce(p->>'mode', '');
  v_mk int; v_name text; v_phone text; v_addr text; v_note text; v_slot text;
  v_lat double precision; v_lng double precision;
  v_items jsonb := '[]'::jsonb; v_goods bigint := 0; v_kg numeric := 0; v_nop int := 0;
  v_car public.delivery_tariffs; v_m jsonb; r record; n int := 0; v_row public.orders;
begin
  if v_uid is null then raise exception 'no_session' using errcode = '28000'; end if;
  if coalesce((select value from public.app_settings where key = 'require_login'), 'true') = 'true' and v_pid is null then
    raise exception 'login_required' using errcode = '28000';
  end if;
  if (select count(*) from public.orders where user_id = v_uid and created_at > now() - interval '1 hour')
     >= coalesce((select value::int from public.app_settings where key = 'orders_per_hour'), 10) then
    raise exception 'too_many' using errcode = '54000';
  end if;
  if v_mode not in ('delivery', 'pickup', 'car') then raise exception 'bad_mode'; end if;

  v_name  := left(trim(coalesce(p->>'name', '')), 60);
  v_phone := left(trim(coalesce(p->>'phone', '')), 30);
  v_addr  := nullif(left(trim(coalesce(p->>'address', '')), 300), '');
  v_note  := nullif(left(trim(coalesce(p->>'note', '')), 500), '');
  v_slot  := nullif(left(trim(coalesce(p->>'slot', '')), 60), '');
  if v_name = '' then raise exception 'name_required'; end if;
  if length(regexp_replace(v_phone, '\D', '', 'g')) < 9 then raise exception 'phone_required'; end if;
  if v_mode in ('delivery', 'car') and v_addr is null then raise exception 'address_required'; end if;
  if v_mode = 'pickup' then v_addr := null; end if;
  begin
    v_lat := (p->>'lat')::double precision; v_lng := (p->>'lng')::double precision;
  exception when others then v_lat := null; v_lng := null; end;
  if v_lat is null or v_lng is null or v_lat not between 36 and 46 or v_lng not between 55 and 74 or v_mode = 'pickup' then
    v_lat := null; v_lng := null;
  end if;
  begin v_mk := nullif(p->>'market_id', '')::int; exception when others then v_mk := null; end;
  if v_mk is not null and not exists (select 1 from public.markets where id = v_mk and active) then raise exception 'bad_market'; end if;

  if v_mode = 'car' then
    select * into v_car from public.delivery_tariffs where id = p->>'car' and active;
    if not found then raise exception 'bad_car'; end if;
    v_m := public.order_money('car', 0, 0, v_mk, v_lat, v_lng, p->>'zone', v_car.id, p->>'provider');
    v_items := jsonb_build_array(jsonb_build_object('id', null, 'n', 'Машина до ' || v_car.cap_kg || ' кг',
                 'q', 1, 'u', 'рейс', 'price', (v_m->>'delivery')::bigint, 'w', false, 'car', v_car.id));
  else
    if v_mk is null then raise exception 'market_required'; end if;
    if jsonb_typeof(p->'items') <> 'array' or jsonb_array_length(p->'items') = 0 then raise exception 'empty_cart'; end if;
    if jsonb_array_length(p->'items') > 100 then raise exception 'too_many_items'; end if;

    for r in
      with req as (
        select (e->>'id')::int as id, sum(round((e->>'q')::numeric, 2)) as q
        from jsonb_array_elements(p->'items') e group by 1
      )
      select req.id, req.q, pr.name, pr.unit, pr.active, pr.weight_kg, cm.best_price, cm.best_shop
      from req left join public.products pr on pr.id = req.id
      left join public.catalog_market cm on cm.market_id = v_mk and cm.id = req.id
      order by req.id
    loop
      if r.name is null or not r.active then raise exception 'unknown_product %', r.id; end if;
      if r.q is null or r.q <= 0 or r.q > 100000 then raise exception 'bad_qty %', r.id; end if;
      n := n + 1;
      v_items := v_items || jsonb_build_object('id', r.id, 'n', r.name, 'q', r.q, 'u', r.unit,
                   'price', coalesce(r.best_price, 0), 'shop', r.best_shop, 'w', false, 'nop', r.best_price is null);
      v_goods := v_goods + round(coalesce(r.best_price, 0) * r.q);
      v_kg := v_kg + r.q * coalesce(r.weight_kg, 1);
      if r.best_price is null then v_nop := v_nop + 1; end if;
    end loop;
    -- минимал буюртма (нархи аниқланмаган товар бўлса суммани билмаймиз — текширмаймиз)
    if v_nop = 0 and v_goods < public.fs('min_order') then raise exception 'min_order'; end if;
    v_m := public.order_money(v_mode, v_goods, v_kg, v_mk, v_lat, v_lng, p->>'zone', nullif(p->>'body', ''), p->>'provider');
  end if;

  insert into public.orders (user_id, profile_id, market_id, customer_name, phone, address, note, mode, slot, total, goods, work,
                             times, items, delivery_lat, delivery_lng,
                             goods_sum, delivery_sum, service_fee, collector_fee, driver_fee, gateway_pct, gateway_fee, platform_income,
                             zone, body, trips, weight_kg, provider)
  values (v_uid, v_pid, v_mk, v_name, v_phone, v_addr, v_note, v_mode,
          case when v_mode = 'car' then coalesce(v_slot, 'Как можно скорее') else v_slot end,
          (v_m->>'total')::bigint, v_mode <> 'car', false,
          jsonb_build_array((extract(epoch from now()) * 1000)::bigint), v_items, v_lat, v_lng,
          (v_m->>'goods')::bigint, (v_m->>'delivery')::bigint, (v_m->>'service')::bigint, (v_m->>'collector_fee')::bigint,
          (v_m->>'driver_fee')::bigint, (v_m->>'gateway_pct')::numeric, (v_m->>'gateway_fee')::bigint, (v_m->>'platform')::bigint,
          v_m->>'zone', v_m->>'body', (v_m->>'trips')::int, (v_m->>'kg')::numeric, v_m->>'provider')
  returning * into v_row;
  perform public.ledger_rebook(v_row.no);
  return v_row;
end $function$;

CREATE OR REPLACE FUNCTION public.create_ticket(p_order_no bigint, p_text text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pid bigint := public.my_profile_id(); tid bigint; txt text := trim(coalesce(p_text, ''));
begin
  if pid is null then raise exception 'login_required' using errcode = '42501'; end if;
  if length(txt) < 3 or length(txt) > 1000 then raise exception 'bad_value'; end if;
  if p_order_no is not null and not exists (select 1 from public.orders where no = p_order_no and (profile_id = pid or user_id = auth.uid())) then raise exception 'not_found'; end if;
  if (select count(*) from public.tickets where profile_id = pid and status <> 'closed') >= 5 then raise exception 'too_many_open'; end if;
  if exists (select 1 from public.ticket_msgs m join public.tickets t on t.id = m.ticket_id where t.profile_id = pid and m.from_role = 'customer' and m.at > now() - interval '20 seconds') then raise exception 'too_fast'; end if;
  insert into public.tickets (profile_id, order_no) values (pid, p_order_no) returning id into tid;
  insert into public.ticket_msgs (ticket_id, from_role, body) values (tid, 'customer', txt);
  perform public.bot_post(jsonb_build_object('alert', '💬 Янги мурожаат №' || tid || coalesce(' (буюртма №' || p_order_no || ')', '') || E'\n' || left(txt, 300)));
  return tid;
end $function$;

CREATE OR REPLACE FUNCTION public.customer_ack(p_no bigint, p_ok boolean, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.orders set received_at = now(), received_ok = p_ok, received_note = left(p_note, 500)
   where no = p_no and received_at is null
     and (user_id = auth.uid() or (profile_id is not null and profile_id = public.my_profile_id()));
end $function$;

CREATE OR REPLACE FUNCTION public.drv_auth(p_session text)
 RETURNS sellers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare d public.sellers; h text := encode(digest(coalesce(p_session, ''), 'sha256'), 'hex');
begin
  select s.* into d from public.driver_sessions ss join public.sellers s on s.id = ss.seller_id
   where ss.token_hash = h and ss.expires_at > now() and s.role = 'driver' and s.status = 'active';
  if not found then raise exception 'not_authorized'; end if;
  update public.driver_sessions set last_seen = now(), expires_at = greatest(expires_at, now() + interval '365 days') where token_hash = h;
  return d;
end $function$;

CREATE OR REPLACE FUNCTION public.drv_claim(p_session text, p_no bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare d public.sellers := public.drv_auth(p_session); mk int;
begin
  select market_id into mk from public.fleets where id = d.fleet_id and active;
  if mk is null then raise exception 'no_fleet'; end if;
  update public.orders set driver_id = d.id, driver_info = jsonb_build_object('name', d.name, 'phone', d.phone, 'car', coalesce(d.car, ''))
   where no = p_no and driver_id is null and stage < 3 and mode = 'delivery' and market_id = mk;
  if not found then return false; end if;
  update public.order_lines set loaded = false where order_no = p_no;
  perform public.bot_post(jsonb_build_object('dm', coalesce((select jsonb_agg(jsonb_build_object('chat_id', a.tg_chat_id,
     'text', '🚚 №' || p_no || ': ҳайдовчи ' || coalesce(d.name, '') || ' иловадан олди.')) from public.sellers a where a.role = 'admin' and a.status = 'active' and a.tg_chat_id is not null), '[]'::jsonb)));
  return true;
end $function$;

CREATE OR REPLACE FUNCTION public.drv_done(p_session text, p_no bigint)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare d public.sellers := public.drv_auth(p_session); o public.orders;
begin
  select * into o from public.orders where no = p_no and driver_id = d.id for update;
  if not found then return 'not_yours'; end if;
  if o.stage < 3 then return 'not_started'; end if;
  if o.stage >= 4 then return 'already'; end if;
  update public.orders set stage = 4, times = coalesce(times, '[]'::jsonb) || to_jsonb((extract(epoch from now()) * 1000)::bigint) where no = p_no;
  perform public.bot_post(jsonb_build_object('dm', coalesce((select jsonb_agg(jsonb_build_object('chat_id', a.tg_chat_id,
     'text', '✅ №' || p_no || ': ' || coalesce(d.name, '') || ' мижозга топширди (иловадан). Мижоз тасдиғи кутилмоқда.')) from public.sellers a where a.role = 'admin' and a.status = 'active' and a.tg_chat_id is not null), '[]'::jsonb)));
  return 'ok';
end $function$;

CREATE OR REPLACE FUNCTION public.drv_go(p_session text, p_no bigint)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare d public.sellers := public.drv_auth(p_session); o public.orders; n int; t jsonb;
begin
  select * into o from public.orders where no = p_no and driver_id = d.id for update;
  if not found then return 'not_yours'; end if;
  if o.stage >= 3 then return 'already'; end if;
  select count(*) into n from public.order_lines where order_no = p_no and status <> 'missing' and seller_id is not null and not loaded;
  if n > 0 then return 'not_loaded'; end if;
  t := coalesce(o.times, '[]'::jsonb);
  for i in o.stage .. 2 loop t := t || to_jsonb((extract(epoch from now()) * 1000)::bigint); end loop;
  update public.orders set stage = 3, times = t, loaded_at = now() where no = p_no;
  return 'ok';
end $function$;

CREATE OR REPLACE FUNCTION public.drv_load(p_session text, p_no bigint, p_line integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare d public.sellers := public.drv_auth(p_session);
begin
  update public.order_lines l set loaded = not l.loaded
   where l.order_no = p_no and l.line_no = p_line and exists (select 1 from public.orders o where o.no = p_no and o.driver_id = d.id and o.stage < 3);
end $function$;

CREATE OR REPLACE FUNCTION public.drv_loc(p_session text, p_lat double precision, p_lng double precision)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare d public.sellers := public.drv_auth(p_session);
begin
  if p_lat is null or p_lng is null or p_lat not between 36 and 46 or p_lng not between 55 and 74 then return; end if;
  update public.orders o set driver_lat = p_lat, driver_lng = p_lng, driver_at = now(),
    eta_min = case when o.delivery_lat is null then null else greatest(2, round(
      6371 * 2 * asin(sqrt(sin(radians(o.delivery_lat - p_lat) / 2) ^ 2 + cos(radians(p_lat)) * cos(radians(o.delivery_lat)) * sin(radians(o.delivery_lng - p_lng) / 2) ^ 2)) * 1.35 / 22 * 60))::int end
   where o.driver_id = d.id and o.stage = 3;
end $function$;

CREATE OR REPLACE FUNCTION public.drv_login_check(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare r public.driver_login; s text; nm text;
begin
  select * into r from public.driver_login where token = p_token;
  if not found or r.created_at < now() - interval '30 minutes' or r.used_at is not null then return jsonb_build_object('status', 'expired'); end if;
  if r.seller_id is null then return jsonb_build_object('status', 'wait'); end if;
  s := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  insert into public.driver_sessions (token_hash, seller_id) values (encode(digest(s, 'sha256'), 'hex'), r.seller_id);
  update public.driver_login set used_at = now() where token = p_token;
  select coalesce(nullif(name, ''), shop) into nm from public.sellers where id = r.seller_id;
  return jsonb_build_object('status', 'ok', 'session', s, 'name', nm);
end $function$;

CREATE OR REPLACE FUNCTION public.drv_login_new()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare t text := replace(gen_random_uuid()::text, '-', '');
begin
  delete from public.driver_login where created_at < now() - interval '1 day';
  insert into public.driver_login (token) values (t);
  return t;
end $function$;

CREATE OR REPLACE FUNCTION public.drv_order_json(o orders)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return jsonb_build_object('no', o.no, 'stage', o.stage, 'address', o.address, 'lat', o.delivery_lat, 'lng', o.delivery_lng,
    'pickup_lat', o.pickup_lat, 'pickup_lng', o.pickup_lng, 'pickup_note', o.pickup_note,
    'customer', o.customer_name, 'phone', o.phone, 'slot', o.slot, 'note', o.note, 'driver_id', o.driver_id,
    'fee', coalesce(o.delivery_sum, 0) - coalesce(o.driver_fee, 0), 'market', (select coalesce(m.name_uz, m.name) from public.markets m where m.id = o.market_id),
    'lines', coalesce((select jsonb_agg(jsonb_build_object('line_no', l.line_no, 'name', l.name, 'qty', l.qty, 'unit', l.unit, 'loaded', l.loaded,
        'shop', coalesce(nullif(s.shop, ''), s.name), 'shop_phone', s.phone) order by l.seller_id, l.line_no)
        from public.order_lines l left join public.sellers s on s.id = l.seller_id where l.order_no = o.no and l.status <> 'missing' and l.seller_id is not null), '[]'::jsonb));
end $function$;

CREATE OR REPLACE FUNCTION public.drv_orders(p_session text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare d public.sellers := public.drv_auth(p_session); mk int;
begin
  select market_id into mk from public.fleets where id = d.fleet_id and active;
  return jsonb_build_object(
    'me', jsonb_build_object('id', d.id, 'name', coalesce(nullif(d.name, ''), d.shop), 'car', d.car, 'fleet', (select name from public.fleets where id = d.fleet_id)),
    'open', coalesce((select jsonb_agg(public.drv_order_json(o) order by o.fleet_dispatched_at) from public.orders o
        where mk is not null and o.market_id = mk and o.mode = 'delivery' and o.driver_id is null and o.stage < 3 and o.fleet_dispatched_at is not null), '[]'::jsonb),
    'mine', coalesce((select jsonb_agg(public.drv_order_json(o) order by o.no desc) from public.orders o
        where o.driver_id = d.id and (o.stage < 4 or o.times ->> 4 is not null and (o.times ->> 4)::bigint > (extract(epoch from now() - interval '2 days') * 1000)::bigint)), '[]'::jsonb),
    'earn', coalesce((select jsonb_build_object('due', b.earned - b.paid, 'waiting', b.waiting, 'held', b.held, 'paid', b.paid) from public.staff_balance_v b where b.seller_id = d.id),
        jsonb_build_object('due', 0, 'waiting', 0, 'held', 0, 'paid', 0)));
end $function$;

CREATE OR REPLACE FUNCTION public.fs(k text)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select value from public.fee_settings where key = k
$function$;

CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.sellers s join public.profiles p on p.tg_id = s.tg_chat_id
                 where p.id = public.my_profile_id() and s.role = 'admin' and s.status = 'active')
      or exists (select 1 from public.admin_users a where a.profile_id = public.my_profile_id() and a.status = 'active')
$function$;

CREATE OR REPLACE FUNCTION public.ledger_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin raise exception 'ledger is append-only'; end $function$;

CREATE OR REPLACE FUNCTION public.ledger_rebook(p_no bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.orders;
begin
  select * into o from public.orders where no = p_no for update;
  if not found or o.total is null or o.pay_status in ('unpaid', 'expired', 'refunded') then return; end if;
  insert into public.ledger (order_no, kind, amount, note, reverses)
    select l.order_no, l.kind, -l.amount, 'тескари ёзув', l.id from public.ledger l
    where l.order_no = p_no and l.reverses is null and l.kind <> 'refund'
      and not exists (select 1 from public.ledger x where x.reverses = l.id);
  insert into public.ledger (order_no, kind, amount)
    select p_no, k, a from (values
      ('customer_payment', coalesce(o.pay_amount, o.total)),
      ('reserve_hold',    -coalesce(o.reserve_sum, 0)),
      ('shop_goods', -(coalesce(o.goods_sum, 0) - coalesce(o.seller_commission, 0))),
      ('driver_pay',      -(coalesce(o.delivery_sum, 0) - coalesce(o.driver_fee, 0))),
      ('collector_pay',   -coalesce(o.collector_fee, 0)),
      ('gateway_fee',     -coalesce(o.gateway_fee, 0)),
      ('platform_income', -coalesce(o.platform_income, 0))
    ) v(k, a) where a <> 0 or k in ('customer_payment', 'platform_income');
end $function$;

CREATE OR REPLACE FUNCTION public.log_event(p_anon text, p_kind text, p_props jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_kind not in ('visit', 'tab', 'search', 'calc', 'cart_add', 'checkout', 'login_start', 'login', 'order') then return; end if;
  if p_anon is null or length(p_anon) not between 8 and 40 then return; end if;
  if p_props is null or jsonb_typeof(p_props) <> 'object' or length(p_props::text) > 1000 then p_props := '{}'::jsonb; end if;
  insert into public.events (anon, kind, props) values (p_anon, p_kind, p_props);
end $function$;

CREATE OR REPLACE FUNCTION public.login_bind(p_token text, p_chat bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.login_tokens set tg_chat_id = p_chat
   where token = p_token and used_at is null and created_at > now() - interval '30 minutes';
  return found;
end $function$;

CREATE OR REPLACE FUNCTION public.login_finish(p_chat bigint, p_phone text, p_name text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tk public.login_tokens; pid bigint; ph text;
begin
  select * into tk from public.login_tokens
   where tg_chat_id = p_chat and used_at is null and created_at > now() - interval '30 minutes'
   order by created_at desc limit 1;
  if not found then return 'no_token'; end if;
  ph := regexp_replace(coalesce(p_phone, ''), '\D', '', 'g');
  if length(ph) < 9 then return 'bad_phone'; end if;
  ph := '+' || ph;
  insert into public.profiles (tg_id, phone, name, consent_at)
  values (p_chat, ph, nullif(left(trim(coalesce(p_name, '')), 60), ''), case when tk.consent then now() end)
  on conflict (tg_id) do update set phone = excluded.phone, last_seen_at = now(),
         name = coalesce(public.profiles.name, excluded.name),
         consent_at = coalesce(public.profiles.consent_at, excluded.consent_at)
  returning id into pid;
  insert into public.profile_devices (uid, profile_id) values (tk.uid, pid)
  on conflict (uid) do update set profile_id = excluded.profile_id, created_at = now();
  update public.orders set profile_id = pid where user_id = tk.uid and profile_id is null;   -- олдинги аноним буюртмалар профилга
  update public.login_tokens set used_at = now(), profile_id = pid where token = tk.token;
  return 'ok';
end $function$;

CREATE OR REPLACE FUNCTION public.login_start(p_consent boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t text;
begin
  if auth.uid() is null then raise exception 'no_session'; end if;
  if (select count(*) from public.login_tokens where uid = auth.uid() and created_at > now() - interval '1 hour') >= 10 then
    raise exception 'too_many' using errcode = '54000';
  end if;
  t := substr(md5(random()::text || clock_timestamp()::text || auth.uid()::text), 1, 24);
  insert into public.login_tokens (token, uid, consent) values (t, auth.uid(), coalesce(p_consent, false));
  return jsonb_build_object('token', t, 'bot', (select value from public.app_settings where key = 'bot_username'));
end $function$;

CREATE OR REPLACE FUNCTION public.logout()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  delete from public.profile_devices where uid = auth.uid()
$function$;

CREATE OR REPLACE FUNCTION public.mask_phone(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$ select case when p is null or length(p) < 8 then p else left(p, 7) || ' *** ' || right(p, 2) end $function$;

CREATE OR REPLACE FUNCTION public.my_order_ok(p_no bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.orders where no = p_no
                 and (user_id = auth.uid() or (profile_id is not null and profile_id = public.my_profile_id())))
$function$;

CREATE OR REPLACE FUNCTION public.my_profile()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object('id', p.id, 'name', p.name, 'phone', p.phone, 'lang', p.lang,
                            'addresses', p.addresses, 'admin', public.is_admin())
  from public.profiles p where p.id = public.my_profile_id()
$function$;

CREATE OR REPLACE FUNCTION public.my_profile_id()
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select profile_id from public.profile_devices where uid = auth.uid()
$function$;

CREATE OR REPLACE FUNCTION public.my_tickets()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pid bigint := public.my_profile_id();
begin
  if pid is null then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'order_no', t.order_no, 'status', t.status, 'decision', t.decision, 'at', t.created_at,
            'msgs', (select coalesce(jsonb_agg(jsonb_build_object('from', m.from_role, 'body', m.body, 'at', m.at) order by m.id), '[]'::jsonb) from public.ticket_msgs m where m.ticket_id = t.id)) order by t.id desc)
          from public.tickets t where t.profile_id = pid), '[]'::jsonb);
end $function$;

CREATE OR REPLACE FUNCTION public.notify_ack()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.received_at is not null and old.received_at is null then
    perform public.bot_post(jsonb_build_object('ack', new.no));
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.notify_bot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.pay_status = 'unpaid' then return new; end if;
  perform public.bot_post(jsonb_build_object('order_no', new.no));
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.order_apply_commission(p_no bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c bigint; o public.orders;
begin
  select * into o from public.orders where no = p_no for update; if not found then return; end if;
  select least(coalesce(sum(commission), 0), coalesce(o.goods_sum, 0)) into c from public.purchases where order_no = p_no and status = 'paid';
  update public.orders set platform_income = coalesce(platform_income, 0) - coalesce(seller_commission, 0) + c, seller_commission = c where no = p_no;
end $function$;

CREATE OR REPLACE FUNCTION public.order_delivered_ms(o orders)
 RETURNS bigint
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select nullif(o.times ->> (case o.mode when 'pickup' then 3 else 4 end), '')::bigint
$function$;

CREATE OR REPLACE FUNCTION public.order_money(p_mode text, p_goods bigint, p_kg numeric, p_mk integer, p_lat double precision, p_lng double precision, p_zone text, p_body text, p_provider text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare z jsonb; b jsonb; G bigint := coalesce(p_goods, 0); D bigint := 0; base bigint := 0; r numeric := 0; pv text := null;
        service bigint; total bigint; cf bigint := 0; dc bigint := 0; gw bigint; plat bigint;
begin
  select code, pct / 100 into pv, r from public.payment_providers
    where enabled order by (code = p_provider) desc, pct, sort limit 1;
  r := coalesce(r, 0);
  z := public.pick_zone(p_mk, p_lat, p_lng, p_zone);
  if p_mode = 'car' then
    b := public.pick_body(0, z->>'zone', p_body, true); D := (b->>'price')::bigint; G := 0;
  elsif p_mode = 'delivery' then
    b := public.pick_body(p_kg, z->>'zone', p_body, false); D := (b->>'price')::bigint;
  end if;
  if p_mode <> 'car' then base := round(public.fs('fixed_fee') + public.tier_amount(G)); end if;
  service := base + round((G + D + base) * r / (1 - r));
  total   := G + D + service;
  if p_mode <> 'car' then
    cf := least(public.fs('collector_max')::bigint, round(public.fs('collector_fixed') + base * public.fs('collector_share') / 100));
  end if;
  dc := round(D * public.fs('driver_pct') / 100);
  gw := round(total * r);
  plat := total - G - (D - dc) - cf - gw;
  return jsonb_build_object('mode', p_mode, 'goods', G, 'delivery', D, 'base', base, 'service', service, 'total', total,
    'collector_fee', cf, 'driver_fee', dc, 'driver_pay', D - dc, 'gateway_pct', r * 100, 'gateway_fee', gw, 'platform', plat,
    'provider', pv, 'zone', z->>'zone', 'zone_auto', (z->>'auto')::boolean, 'km', z->'km',
    'body', b->>'body', 'body_name', b->>'name', 'cap', b->'cap', 'trips', coalesce((b->>'trips')::int, 0), 'kg', coalesce(p_kg, 0));
end $function$;

CREATE OR REPLACE FUNCTION public.order_payout_state(o orders)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case
    when o.payout_release or o.received_ok is true then 'free'
    when o.received_ok is false then 'hold'
    when public.order_delivered_ms(o) is null then 'free'
    when public.order_delivered_ms(o) <= (extract(epoch from now() - make_interval(hours => coalesce((select value::int from public.app_settings where key = 'payout_hold_hours'), 24))) * 1000)::bigint then 'free'
    else 'wait' end
$function$;

CREATE OR REPLACE FUNCTION public.order_price_for(o orders, r numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare G bigint := coalesce(o.goods_sum, 0); D bigint := coalesce(o.delivery_sum, 0); r0 numeric := coalesce(o.gateway_pct, 0) / 100; k0 numeric; base bigint; svc bigint; tot bigint; gw bigint; plat bigint;
begin
  k0 := r0 / (1 - r0);
  -- асосий хизмат ҳақи (тизим фоизисиз қисми) — сақланган сумма ва фоиздан тикланади
  base := greatest(0, round((coalesce(o.service_fee, 0) - (G + D) * k0) * (1 - r0)));
  svc := base + round((G + D + base) * r / (1 - r));
  tot := G + D + svc;
  gw := round(tot * r);
  plat := tot - G - (D - coalesce(o.driver_fee, 0)) - coalesce(o.collector_fee, 0) - gw;
  return jsonb_build_object('service', svc, 'total', tot, 'gateway_fee', gw, 'platform', plat, 'pay_amount', tot + coalesce(o.reserve_sum, 0));
end $function$;

CREATE OR REPLACE FUNCTION public.order_reprice(p_no bigint, p_provider text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.orders; r numeric; v jsonb;
begin
  select * into o from public.orders where no = p_no for update;
  if not found or o.pay_status <> 'unpaid' then return; end if;
  select pct / 100 into r from public.payment_providers where code = p_provider and enabled;
  if r is null then return; end if;
  v := public.order_price_for(o, r);
  update public.orders set service_fee = (v->>'service')::bigint, total = (v->>'total')::bigint, gateway_pct = r * 100, gateway_fee = (v->>'gateway_fee')::bigint,
         platform_income = (v->>'platform')::bigint, pay_amount = (v->>'pay_amount')::bigint, pay_provider = p_provider where no = p_no;
end $function$;

CREATE OR REPLACE FUNCTION public.orders_pay_init()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pct numeric := coalesce((select value::numeric from public.app_settings where key = 'reserve_pct'), 5);
        mins int := coalesce((select value::int from public.app_settings where key = 'pay_minutes'), 30);
begin
  if coalesce((select value from public.app_settings where key = 'payments_on'), 'false') = 'true' then
    new.pay_status  := 'unpaid';
    new.pay_due     := now() + make_interval(mins => mins);
    new.reserve_sum := case when new.mode = 'car' then 0 else round(coalesce(new.goods_sum, 0) * pct / 100) end;
    new.pay_amount  := new.total + new.reserve_sum;
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.pay_cancel(p_provider text, p_trans_id text, p_ext jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pm public.payments;
begin
  select * into pm from public.payments where provider = p_provider and provider_trans_id = p_trans_id for update;
  if not found then return jsonb_build_object('r', 'not_found'); end if;
  if pm.status = 'cancelled' then return jsonb_build_object('r', 'ok', 'again', true, 'cancelled_at', pm.cancelled_at); end if;
  if pm.status = 'paid' then return jsonb_build_object('r', 'cannot'); end if;
  update public.payments set status = 'cancelled', cancelled_at = now(), ext = ext || coalesce(p_ext, '{}'::jsonb) where id = pm.id;
  return jsonb_build_object('r', 'ok', 'cancelled_at', now());
end $function$;

CREATE OR REPLACE FUNCTION public.pay_check(p_no bigint, p_amount bigint)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.orders;
begin
  select * into o from public.orders where no = p_no;
  if not found or o.pay_status = 'none' then return 'not_found'; end if;
  if o.pay_status = 'paid' then return 'already_paid'; end if;
  if o.pay_status = 'refunded' then return 'cancelled'; end if;
  if o.pay_status = 'expired' or o.pay_due < now() then return 'expired'; end if;
  if p_amount is distinct from o.pay_amount then return 'bad_amount'; end if;
  return 'ok';
end $function$;

CREATE OR REPLACE FUNCTION public.pay_complete(p_provider text, p_trans_id text, p_force boolean DEFAULT false, p_ext jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pm public.payments; o public.orders;
begin
  select * into pm from public.payments where provider = p_provider and provider_trans_id = p_trans_id for update;
  if not found then return jsonb_build_object('r', 'not_found'); end if;
  if pm.status = 'paid' then return jsonb_build_object('r', 'ok', 'again', true, 'paid_at', pm.paid_at, 'order_no', pm.order_no); end if;
  if pm.status = 'cancelled' then return jsonb_build_object('r', 'cancelled'); end if;
  select * into o from public.orders where no = pm.order_no for update;
  if o.pay_status = 'paid' then return jsonb_build_object('r', 'cancelled'); end if;       -- бошқа тўлов аллақачон тўлаган
  if o.pay_status = 'refunded' then return jsonb_build_object('r', 'cancelled'); end if;
  if o.pay_status = 'expired' and not p_force then return jsonb_build_object('r', 'expired'); end if;
  update public.payments set status = 'paid', paid_at = now(), ext = ext || coalesce(p_ext, '{}'::jsonb) where id = pm.id;
  update public.orders set pay_status = 'paid', paid_at = now(), pay_provider = pm.provider where no = pm.order_no;
  perform public.ledger_rebook(pm.order_no);
  perform public.bot_post(jsonb_build_object('order_no', pm.order_no));     -- энди йиғувчиларга ва админга боради
  return jsonb_build_object('r', 'ok', 'paid_at', now(), 'order_no', pm.order_no);
end $function$;

CREATE OR REPLACE FUNCTION public.pay_create(p_provider text, p_trans_id text, p_no bigint, p_amount bigint, p_ext jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pm public.payments; chk text;
begin
  select * into pm from public.payments where provider = p_provider and provider_trans_id = p_trans_id;
  if found then
    return jsonb_build_object('r', 'ok', 'id', pm.id, 'status', pm.status, 'created_at', pm.created_at, 'ext', pm.ext, 'order_no', pm.order_no, 'amount', pm.amount, 'again', true);
  end if;
  perform 1 from public.orders where no = p_no for update;
  chk := public.pay_check(p_no, p_amount);
  if chk <> 'ok' then return jsonb_build_object('r', chk); end if;
  -- бошқа тўлов тизими/транзакция шу буюртма учун ҳозир очиқ бўлса (15 дақиқа ичида) — банд
  if exists (select 1 from public.payments where order_no = p_no and status = 'created'
             and created_at > now() - interval '15 minutes' and not (provider = p_provider and provider_trans_id = p_trans_id)) then
    return jsonb_build_object('r', 'busy');
  end if;
  insert into public.payments (order_no, provider, provider_trans_id, amount, ext)
    values (p_no, p_provider, p_trans_id, p_amount, coalesce(p_ext, '{}'::jsonb)) returning * into pm;
  return jsonb_build_object('r', 'ok', 'id', pm.id, 'status', pm.status, 'created_at', pm.created_at, 'ext', pm.ext, 'order_no', pm.order_no, 'amount', pm.amount);
end $function$;

CREATE OR REPLACE FUNCTION public.pay_expire()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  with x as (
    update public.orders o set pay_status = 'expired'
     where o.pay_status = 'unpaid' and o.pay_due < now()
       and not exists (select 1 from public.payments p where p.order_no = o.no and p.status = 'created' and p.created_at > now() - interval '15 minutes')
    returning 1)
  select count(*) into n from x;
  return n;
end $function$;

CREATE OR REPLACE FUNCTION public.pay_get(p_provider text, p_trans_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object('id', id, 'order_no', order_no, 'amount', amount, 'status', status, 'ext', ext,
                            'created_at', created_at, 'paid_at', paid_at, 'cancelled_at', cancelled_at, 'trans_id', provider_trans_id)
  from public.payments where provider = p_provider and provider_trans_id = p_trans_id
$function$;

CREATE OR REPLACE FUNCTION public.pay_options(p_no bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.orders;
begin
  if not public.my_order_ok(p_no) then return '[]'::jsonb; end if;
  select * into o from public.orders where no = p_no;
  if not found or o.pay_status <> 'unpaid' then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('code', p.code, 'name', p.name, 'pct', p.pct,
            'service', (public.order_price_for(o, p.pct / 100)->>'service')::bigint,
            'pay_amount', (public.order_price_for(o, p.pct / 100)->>'pay_amount')::bigint) order by p.sort) from public.payment_providers p where p.enabled), '[]'::jsonb);
end $function$;

CREATE OR REPLACE FUNCTION public.pay_start(p_no bigint, p_provider text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.orders; s jsonb; ret text; q text; u text;
begin
  if not public.my_order_ok(p_no) then return jsonb_build_object('error', 'not_found'); end if;
  select * into o from public.orders where no = p_no;
  if o.pay_status <> 'unpaid' then return jsonb_build_object('error', o.pay_status); end if;
  if o.pay_due < now() then return jsonb_build_object('error', 'expired'); end if;
  perform public.order_reprice(p_no, p_provider); select * into o from public.orders where no = p_no;
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into s from public.app_settings
    where key in ('click_service_id', 'click_merchant_id', 'payme_merchant_id', 'site_url', 'pay_live');
  ret := coalesce(nullif(s->>'site_url', ''), '') || '?pay=' || p_no;
  if p_provider = 'click' then
    if coalesce(s->>'click_service_id', '') = '' or coalesce(s->>'click_merchant_id', '') = '' then return jsonb_build_object('error', 'not_configured'); end if;
    u := 'https://my.click.uz/services/pay?service_id=' || (s->>'click_service_id') || '&merchant_id=' || (s->>'click_merchant_id')
         || '&amount=' || o.pay_amount || '.00&transaction_param=' || p_no || '&return_url=' || replace(replace(replace(replace(ret, ':', '%3A'), '/', '%2F'), '?', '%3F'), '=', '%3D');
    return jsonb_build_object('url', u, 'amount', o.pay_amount);
  elsif p_provider = 'payme' then
    if coalesce(s->>'payme_merchant_id', '') = '' then return jsonb_build_object('error', 'not_configured'); end if;
    q := 'm=' || (s->>'payme_merchant_id') || ';ac.order_id=' || p_no || ';a=' || (o.pay_amount * 100) || ';l=uz;c=' || ret;
    u := case when s->>'pay_live' = 'true' then 'https://checkout.paycom.uz/' else 'https://test.paycom.uz/' end
         || regexp_replace(encode(convert_to(q, 'UTF8'), 'base64'), '\s', '', 'g');
    return jsonb_build_object('url', u, 'amount', o.pay_amount);
  end if;
  return jsonb_build_object('error', 'bad_provider');
end $function$;

CREATE OR REPLACE FUNCTION public.pay_statement(p_provider text, p_from bigint, p_to bigint)
 RETURNS SETOF jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object('id', id, 'order_no', order_no, 'amount', amount, 'status', status, 'ext', ext, 'trans_id', provider_trans_id)
  from public.payments
  where provider = p_provider and coalesce((ext->>'time')::bigint, 0) between p_from and p_to order by id
$function$;

CREATE OR REPLACE FUNCTION public.pay_test(p_no bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.orders; tid text := 'T' || p_no || '-' || (extract(epoch from clock_timestamp()) * 1000)::bigint; r jsonb;
begin
  if coalesce((select value from public.app_settings where key = 'pay_test_mode'), 'false') <> 'true' then
    return jsonb_build_object('error', 'test_off');
  end if;
  if not public.my_order_ok(p_no) then return jsonb_build_object('error', 'not_found'); end if;
  select * into o from public.orders where no = p_no;
  r := public.pay_create('test', tid, p_no, o.pay_amount);
  if r->>'r' <> 'ok' then return jsonb_build_object('error', r->>'r'); end if;
  r := public.pay_complete('test', tid);
  return jsonb_build_object('ok', r->>'r' = 'ok', 'r', r->>'r');
end $function$;

CREATE OR REPLACE FUNCTION public.pick_body(p_kg numeric, p_zone text, p_body text DEFAULT NULL::text, p_exact boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b public.delivery_tariffs; trips int := 1; need int := 0; price bigint;
begin
  if p_exact then
    select * into b from public.delivery_tariffs where id = p_body and active;
    if not found then raise exception 'bad_car'; end if;
  else
    select coalesce(cap_kg, 0) into need from public.delivery_tariffs where id = p_body and active;
    select * into b from public.delivery_tariffs
      where active and cap_kg >= coalesce(p_kg, 0) and cap_kg >= coalesce(need, 0) order by cap_kg limit 1;
    if not found then
      select * into b from public.delivery_tariffs where active order by cap_kg desc limit 1;
      if not found then raise exception 'no_tariff'; end if;
      trips := greatest(1, ceil(coalesce(p_kg, 0) / b.cap_kg)::int);
    end if;
  end if;
  price := case p_zone when 'near' then b.near_price when 'far' then b.far_price else b.mid_price end;
  return jsonb_build_object('body', b.id, 'name', b.name, 'cap', b.cap_kg, 'trips', trips, 'unit_price', price, 'price', price * trips);
end $function$;

CREATE OR REPLACE FUNCTION public.pick_zone(p_mk integer, p_lat double precision, p_lng double precision, p_zone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m record; km double precision; z text; au boolean := false;
begin
  select lat, lng into m from public.markets where id = p_mk;
  if m.lat is not null and m.lng is not null and p_lat is not null and p_lng is not null then
    km := 6371 * 2 * asin(sqrt(sin(radians(p_lat - m.lat) / 2) ^ 2 + cos(radians(m.lat)) * cos(radians(p_lat)) * sin(radians(p_lng - m.lng) / 2) ^ 2));
    z := case when km <= public.fs('zone_near_km') then 'near' when km <= public.fs('zone_mid_km') then 'mid' else 'far' end;
    au := true;
  elsif p_zone in ('near', 'mid', 'far') then z := p_zone;
  else z := (array['near', 'mid', 'far'])[least(3, greatest(1, public.fs('default_zone_idx')::int))];
  end if;
  return jsonb_build_object('zone', z, 'auto', au, 'km', case when au then round(km::numeric, 1) end);
end $function$;

CREATE OR REPLACE FUNCTION public.profile_set_name(p_name text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.profiles set name = nullif(left(trim(p_name), 60), '') where id = public.my_profile_id()
$function$;

CREATE OR REPLACE FUNCTION public.public_settings()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select jsonb_object_agg(key, case when key = 'car_prices' then value::jsonb else to_jsonb(value) end)
                   from public.app_settings where key in ('delivery_fee', 'car_prices', 'require_login', 'bot_username',
                                                         'payments_on', 'reserve_pct', 'pay_test_mode', 'pay_minutes')), '{}'::jsonb)
    || jsonb_build_object(
         'bodies', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'n', name, 'cap', cap_kg, 'near', near_price, 'mid', mid_price,
                               'far', far_price, 'hint', hint, 'e', emoji) order by sort) from public.delivery_tariffs where active), '[]'::jsonb),
         'providers', coalesce((select jsonb_agg(jsonb_build_object('code', code, 'n', name, 'pct', pct) order by sort)
                                from public.payment_providers where enabled), '[]'::jsonb))
$function$;

CREATE OR REPLACE FUNCTION public.purchases_commission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pct numeric; own numeric; n int; cnt bigint;
        def numeric := coalesce((select value::numeric from public.app_settings where key = 'seller_commission_pct'), 0);
begin
  select commission_pct into own from public.sellers where id = new.shop_id;
  if own is not null then pct := own;
  else
    pct := def;
    n := coalesce((select value::int from public.app_settings where key = 'commission_free_orders'), 0);
    if n > 0 then
      -- шу дўкондаги буюртмалар биринчи харид тартиби бўйича: ўз тартиб рақами N дан кичик бўлса — бепул
      with f as (select p.order_no k, min(p.id) first_id
                   from public.purchases p
                  where p.shop_id = new.shop_id and p.status in ('pending', 'paid') group by 1)
      select case when exists (select 1 from f where k = new.order_no) then (select count(*) from f where first_id < (select first_id from f where k = new.order_no))
                  else (select count(*) from f) end into cnt;
      if cnt < n then pct := 0; end if;
    end if;
  end if;
  new.commission_pct := pct; new.commission := round(new.total * pct / 100);
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.purchases_paid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'paid' and old.status is distinct from 'paid' then
    perform public.order_apply_commission(new.order_no);
    perform public.ledger_rebook(new.order_no);
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.quote_order(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_mk int; v_goods bigint := 0; v_nop int := 0; v_kg numeric := 0; v_mode text := coalesce(p->>'mode', 'delivery');
        v_lat double precision; v_lng double precision; v_m jsonb; v_out jsonb; v_res bigint := 0;
begin
  begin v_mk := nullif(p->>'market_id', '')::int; exception when others then v_mk := null; end;
  begin v_lat := (p->>'lat')::double precision; v_lng := (p->>'lng')::double precision; exception when others then v_lat := null; v_lng := null; end;
  if v_mode not in ('delivery', 'pickup', 'car') then v_mode := 'delivery'; end if;
  if v_mode = 'car' then
    v_m := public.order_money('car', 0, 0, v_mk, v_lat, v_lng, p->>'zone', p->>'car', p->>'provider');
    v_out := v_m || jsonb_build_object('nop', 0);
  else
    select coalesce(sum(round(coalesce(cm.best_price, 0) * q.q)), 0), count(*) filter (where cm.best_price is null),
           coalesce(sum(q.q * coalesce(pr.weight_kg, 1)), 0)
      into v_goods, v_nop, v_kg
    from (select (e->>'id')::int as id, sum(round((e->>'q')::numeric, 2)) as q from jsonb_array_elements(coalesce(p->'items', '[]')) e group by 1) q
    left join public.products pr on pr.id = q.id
    left join public.catalog_market cm on cm.market_id = v_mk and cm.id = q.id;
    v_m := public.order_money(v_mode, v_goods, v_kg, v_mk, v_lat, v_lng, p->>'zone', nullif(p->>'body', ''), p->>'provider');
    v_out := v_m || jsonb_build_object('nop', v_nop, 'min_order', public.fs('min_order'),
      'short', case when v_nop = 0 then greatest(public.fs('min_order') - v_goods, 0) else 0 end);
    if coalesce((select value from public.app_settings where key = 'payments_on'), 'false') = 'true' then
      v_res := round(v_goods * coalesce((select value::numeric from public.app_settings where key = 'reserve_pct'), 5) / 100);
    end if;
  end if;
  return v_out || jsonb_build_object('reserve', v_res, 'pay_total', (v_m->>'total')::bigint + v_res);
end $function$;

CREATE OR REPLACE FUNCTION public.tier_amount(g bigint)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t1 numeric := public.fs('tier1_max'); t2 numeric := public.fs('tier2_max');
        p1 numeric := public.fs('tier1_pct'); p2 numeric := public.fs('tier2_pct'); p3 numeric := public.fs('tier3_pct');
begin
  if public.fs('tier_mode') = 1 then
    return least(g, t1) * p1 / 100 + greatest(least(g, t2) - t1, 0) * p2 / 100 + greatest(g - t2, 0) * p3 / 100;
  end if;
  return g * (case when g <= t1 then p1 when g <= t2 then p2 else p3 end) / 100;
end $function$;

-- 5. View'лар
create view public.catalog_market as
 SELECT m.id AS market_id,
    p.id,
    b.price AS best_price,
    b.shop AS best_shop,
    (COALESCE(c.n, (0)::bigint))::integer AS offers
   FROM (((markets m
     CROSS JOIN products p)
     LEFT JOIN LATERAL ( SELECT o.price,
            s.shop
           FROM (offers o
             JOIN sellers s ON ((s.id = o.seller_id)))
          WHERE ((o.product_id = p.id) AND o.in_stock AND (s.status = 'active'::text) AND (s.role = 'seller'::text) AND ((s.market_id = m.id) OR (s.market_id IS NULL)))
          ORDER BY o.price
         LIMIT 1) b ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS n
           FROM (offers o
             JOIN sellers s ON ((s.id = o.seller_id)))
          WHERE ((o.product_id = p.id) AND o.in_stock AND (s.status = 'active'::text) AND (s.role = 'seller'::text) AND ((s.market_id = m.id) OR (s.market_id IS NULL)))) c ON (true))
  WHERE (m.active AND p.active AND (b.price IS NOT NULL));

create view public.catalog_public as
 SELECT p.id,
    p.cat,
    p.name,
    p.spec,
    p.unit,
    p.emoji,
    p.base_price,
    b.price AS best_price,
    b.shop AS best_shop,
    (COALESCE(c.n, (0)::bigint))::integer AS offers
   FROM ((products p
     LEFT JOIN LATERAL ( SELECT o.price,
            s.shop
           FROM (offers o
             JOIN sellers s ON ((s.id = o.seller_id)))
          WHERE ((o.product_id = p.id) AND o.in_stock AND (s.status = 'active'::text) AND (s.role = 'seller'::text))
          ORDER BY o.price
         LIMIT 1) b ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS n
           FROM (offers o
             JOIN sellers s ON ((s.id = o.seller_id)))
          WHERE ((o.product_id = p.id) AND o.in_stock AND (s.status = 'active'::text) AND (s.role = 'seller'::text))) c ON (true))
  WHERE p.active;

create view public.earnings as
 SELECT no AS order_no,
    created_at,
    mode,
    stage,
    picker_id AS collector_id,
    collector_fee,
    driver_id,
    (COALESCE(delivery_sum, (0)::bigint) - COALESCE(driver_fee, (0)::bigint)) AS driver_pay,
    platform_income,
    gateway_fee,
    goods_sum,
    delivery_sum,
    service_fee,
    total
   FROM orders o;

create view public.ledger_check as
 SELECT order_no,
    sum(amount) AS diff
   FROM ledger
  GROUP BY order_no
 HAVING (sum(amount) <> (0)::numeric);

create view public.markets_public as
 WITH r AS (
         SELECT cm.market_id,
            ((cm.best_price)::numeric / avg(cm.best_price) OVER (PARTITION BY cm.id)) AS ratio,
            count(*) OVER (PARTITION BY cm.id) AS nm
           FROM catalog_market cm
        ), pi AS (
         SELECT r.market_id,
            (avg(r.ratio))::numeric(6,3) AS price_index,
            (count(*))::integer AS price_n
           FROM r
          WHERE (r.nm >= 2)
          GROUP BY r.market_id
        )
 SELECT m.id,
    m.name,
    m.name_uz,
    m.district,
    m.address,
    m.lat,
    m.lng,
    m.size,
    m.sort,
    (( SELECT count(*) AS count
           FROM sellers s
          WHERE ((s.market_id = m.id) AND (s.role = 'seller'::text) AND (s.status = 'active'::text))))::integer AS shops,
    (( SELECT count(*) AS count
           FROM sellers s
          WHERE ((s.market_id = m.id) AND (s.role = 'collector'::text) AND (s.status = 'active'::text))))::integer AS pickers,
    pi.price_index,
    COALESCE(pi.price_n, 0) AS price_n
   FROM (markets m
     LEFT JOIN pi ON ((pi.market_id = m.id)))
  WHERE m.active;

create view public.payments_view as
 SELECT p.id,
    p.order_no,
    p.provider,
    p.provider_trans_id,
    p.amount,
    p.status,
    p.created_at,
    p.paid_at,
    o.pay_status
   FROM (payments p
     JOIN orders o ON ((o.no = p.order_no)))
  ORDER BY p.id DESC;

create view public.staff_balance_v as
 WITH earned AS (
         SELECT o.picker_id AS seller_id,
            o.no,
            COALESCE(o.collector_fee, (0)::bigint) AS amt,
            order_payout_state(o.*) AS st
           FROM orders o
          WHERE ((o.picker_id IS NOT NULL) AND (o.pay_status = ANY (ARRAY['paid'::text, 'none'::text])) AND (o.stage >=
                CASE o.mode
                    WHEN 'pickup'::text THEN 3
                    ELSE 4
                END))
        UNION ALL
         SELECT o.driver_id,
            o.no,
            (COALESCE(o.delivery_sum, (0)::bigint) - COALESCE(o.driver_fee, (0)::bigint)),
            order_payout_state(o.*) AS order_payout_state
           FROM orders o
          WHERE ((o.driver_id IS NOT NULL) AND (o.pay_status = ANY (ARRAY['paid'::text, 'none'::text])) AND (o.stage >=
                CASE o.mode
                    WHEN 'pickup'::text THEN 3
                    ELSE 4
                END))
        )
 SELECT s.id AS seller_id,
    s.role,
    COALESCE(NULLIF(s.name, ''::text), s.shop) AS name,
    s.phone,
    s.card,
    s.status,
    (COALESCE(sum(e.amt) FILTER (WHERE (e.st = 'free'::text)), (0)::numeric))::bigint AS earned,
    (count(e.no) FILTER (WHERE (e.st = 'free'::text)))::integer AS orders,
    (COALESCE(( SELECT sum(p.amount) AS sum
           FROM staff_payouts p
          WHERE (p.seller_id = s.id)), (0)::numeric))::bigint AS paid,
    (COALESCE(sum(e.amt) FILTER (WHERE (e.st = 'wait'::text)), (0)::numeric))::bigint AS waiting,
    (COALESCE(sum(e.amt) FILTER (WHERE (e.st = 'hold'::text)), (0)::numeric))::bigint AS held
   FROM (sellers s
     LEFT JOIN earned e ON ((e.seller_id = s.id)))
  WHERE (s.role = ANY (ARRAY['collector'::text, 'driver'::text]))
  GROUP BY s.id;

-- 6. Триггерлар
CREATE TRIGGER audit_no_change BEFORE DELETE OR UPDATE ON public.audit_log FOR EACH ROW EXECUTE FUNCTION audit_immutable();
CREATE TRIGGER audit_no_truncate BEFORE TRUNCATE ON public.audit_log FOR EACH STATEMENT EXECUTE FUNCTION audit_immutable();
CREATE TRIGGER ledger_no_change BEFORE DELETE OR UPDATE ON public.ledger FOR EACH ROW EXECUTE FUNCTION ledger_immutable();
CREATE TRIGGER ledger_no_truncate BEFORE TRUNCATE ON public.ledger FOR EACH STATEMENT EXECUTE FUNCTION ledger_immutable();
CREATE TRIGGER notes_no_change BEFORE DELETE OR UPDATE ON public.notes FOR EACH ROW EXECUTE FUNCTION audit_immutable();
CREATE TRIGGER orders_notify_ack AFTER UPDATE OF received_at ON public.orders FOR EACH ROW EXECUTE FUNCTION notify_ack();
CREATE TRIGGER orders_notify_bot AFTER INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION notify_bot();
CREATE TRIGGER orders_pay_init BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION orders_pay_init();
CREATE TRIGGER price_hist_no_change BEFORE DELETE OR UPDATE ON public.price_history FOR EACH ROW EXECUTE FUNCTION audit_immutable();
CREATE TRIGGER purchases_commission_ins BEFORE INSERT ON public.purchases FOR EACH ROW EXECUTE FUNCTION purchases_commission();
CREATE TRIGGER purchases_paid_upd AFTER UPDATE OF status ON public.purchases FOR EACH ROW EXECUTE FUNCTION purchases_paid();
CREATE TRIGGER staff_payouts_no_change BEFORE DELETE OR UPDATE ON public.staff_payouts FOR EACH ROW EXECUTE FUNCTION audit_immutable();
CREATE TRIGGER ticket_msgs_no_change BEFORE DELETE OR UPDATE ON public.ticket_msgs FOR EACH ROW EXECUTE FUNCTION audit_immutable();

